  add(1,0,'Low tide','midi',{notes:notes([33,33,36,31],.7)});add(1,1,'Sub motion','midi',{notes:notes([33,40,36,43],.75)});add(1,3,'Home again','midi',{notes:notes([33,33,36,31],.9)});
