$('mixer').addEventListener('input',run(e=>{const channel=e.target.closest('[data-channel]');if(channel){const t=project.tracks.find(t=>t.id===channel.dataset.channel);if(e.target.hasAttribute('data-crossfade'))t.crossfade=e.target.value;if(e.target.dataset.send)engine.setSendLevel(t.id,e.target.dataset.send,Number(e.target.value));if(e.target.dataset.pre)engine.setSendPre(t.id,e.target.dataset.pre,e.target.checked);if(e.target.hasAttribute('data-output'))t.output=e.target.value;if(e.target.hasAttribute('data-volume')){t.volume=Number(e.target.value);engine.overrideAutomation(t.id,'volume');channel.querySelector('[data-volume-label]').textContent=Math.round(t.volume*100)+'%';}if(e.target.hasAttribute('data-pan')){t.pan=Number(e.target.value);engine.overrideAutomation(t.id,'pan');channel.querySelector('[data-pan-label]').textContent=panLabel(t.pan);}}else if(['crossfader','crossfade-curve'].includes(e.target.id)){project.crossfade??={position:0,curve:'blend'};if(e.target.id==='crossfader'){project.crossfade.position=Number(e.target.value);$('crossfader-value').textContent=crossfadeLabel(project.crossfade.position);}else project.crossfade.curve=e.target.value;}else if(e.target.id==='master'){engine.masterVolume=Number(e.target.value);project.master=engine.masterVolume;$('master-label').textContent=Math.round(engine.masterVolume*100)+'%';}engine.updateMix();clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist().catch(()=>{}),600);}));
