captureButton.onclick=run(()=>{if(busy||inputActive())throw new Error('Finish the current operation or input take first.');const {index,copies}=engine.captureScene(Math.min(selectedSessionScene,project.scenes-1));selectedSessionScene=index;const first=copies[0];if(first)selection={trackId:first.trackId,clipId:first.id,scene:index};selectedRegion=null;render();$('manage-scene').value=index;changed();document.querySelector(`[data-scene-launch="${index}"]`)?.scrollIntoView({block:'nearest',inline:'nearest'});setStatus(`Captured ${copies.length} running clips in scene ${index+1}. Playback continues; queued launches are retained.`);});
$('add-track').onclick=run(()=>newTrack());$('add-scene').onclick=run(()=>{stopToEdit();if(project.scenes>=32)throw new Error('This prototype supports up to 32 scenes.');project.scenes++;project.sceneFollows?.push(null);project.tracks.forEach(t=>t.slots.push(null));render();changed();});
$('add-to-arrangement').onclick=run(()=>{stopToEdit();const c=project.clips[selection?.clipId];if(!c)throw new Error('Select a Session clip first.');const start=Math.ceil(Math.max(0,...project.arrangement.filter(s=>s.trackId===selection.trackId).map(s=>s.start+s.length))*4)/4;const s={id:uid(),clipId:c.id,trackId:selection.trackId,start,length:c.beats,offset:0};project.arrangement.push(s);selectedRegion=s.id;render();changed();});
$('import').onclick=run(()=>{stopToEdit();importTarget=null;$('audio-file').click();});$('audio-file').onchange=run(async e=>{await importAudio(e.target.files[0],importTarget);e.target.value='';});
// File-menu lifecycle commands retain one previous set in the same atomic write.
const lifecycle=document.createElement('div');lifecycle.hidden=true;document.body.append(lifecycle);
for(const id of ['new-set','save-default-set','reset-default-set','restore-previous-set','save-template','open-templates']){const button=document.createElement('button');button.id=id;lifecycle.append(button);}
async function readSet(key){const db=await dbPromise;return new Promise((resolve,reject)=>{const r=db.transaction('projects').objectStore('projects').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function writeSets(entries){const db=await dbPromise;await new Promise((resolve,reject)=>{const tx=db.transaction('projects','readwrite'),store=tx.objectStore('projects');try{for(const [key,value] of entries)value===null?store.delete(key):store.put(value,key);}catch(error){tx.abort();reject(error);return;}tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error||new Error('Could not save this set.'));tx.onerror=()=>reject(tx.error);});}
async function withSetLock(fn){if(busy)throw new Error('Wait for the current operation to finish.');stopToEdit();if(engine.recording||engine.automationTake)throw new Error('Stop recording first.');busy=true;renderTransport();clearTimeout(saveTimer);try{return await fn();}finally{busy=false;renderTransport();clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist().catch(()=>{$('save-state').textContent='Autosave unavailable · download a project';}),600);}}
const lifecycleRun=fn=>run(()=>withSetLock(fn));
