function inputNote(type,key,pitch,velocity=type==='on'?.75:0){if(!liveNotes)return;const time=engine.context.currentTime;if(type==='on'){liveNotes.on(key,pitch,velocity,inputActive()?inputTarget:$('input-track').value);if(time>=inputStarted)midiTake?.on(key,pitch,velocity,time);}else{liveNotes.off(key,velocity);midiTake?.off(key,time,velocity);}}
function releaseNotes(){liveNotes?.allOff();midiSustain.reset();if(midiTake)for(const key of [...midiTake.held.keys()])midiTake.off(key,engine.context.currentTime);}
function bindMidi(){if(midiPort)midiPort.onmidimessage=null;releaseNotes();midiPort=midiAccess?.inputs.get($('midi-device').value);if(midiPort)midiPort.onmidimessage=event=>{const n=decodeMidi(event.data);if(n)midiSustain.handle(n);};}
function refreshMidi(){const select=$('midi-device'),old=select.value;select.innerHTML=[...midiAccess.inputs.values()].filter(p=>p.state==='connected').map(p=>`<option value="${esc(p.id)}">${esc(p.name||'MIDI input')}</option>`).join('')||'<option value="">No MIDI input available</option>';if([...select.options].some(o=>o.value===old))select.value=old;bindMidi();}
async function refreshAudioDevices(){if(!navigator.mediaDevices?.enumerateDevices)throw new Error('Audio device listing is unavailable in this browser.');const generation=++audioListGeneration,devices=await navigator.mediaDevices.enumerateDevices();if(generation!==audioListGeneration)return;const select=$('audio-device'),selected=select.value;select.innerHTML=audioInputChoices(devices,selected).map(d=>`<option value="${esc(d.id)}" ${d.missing?'disabled':''}>${esc(d.label)}</option>`).join('');select.value=selected;}
$('audio-refresh').onclick=run(refreshAudioDevices);
$('audio-channels').innerHTML=Array.from({length:16},(_,i)=>`<option value="stereo:${i*2}">Stereo ${i*2+1}/${i*2+2}</option>`).join('')+Array.from({length:32},(_,i)=>`<option value="mono:${i}">Mono ${i+1}</option>`).join('');
$('audio-channels').onchange=run(async()=>{if(inputActive())return;if(audioInput?.connected)await enableInput();});
$('audio-device').onchange=run(async()=>{if(inputActive())return;if(audioInput?.connected)await enableInput();});
navigator.mediaDevices?.addEventListener('devicechange',()=>refreshAudioDevices().catch(()=>{}));
$('input-connect').onclick=run(enableInput);$('input-record').onclick=run(startInput);$('input-finish').onclick=run(finishInput);
$('input-disconnect').onclick=run(async()=>{await finishInput();releaseInputs();$('input-status').textContent='Inputs disconnected. Microphone released and keyboard disabled.';renderInput();});
$('input-monitor').onchange=()=>audioInput?.setMonitor($('input-monitor').checked);
$('input-track').onchange=run(async()=>{releaseNotes();await engine.prepareSamples();});$('input-kind').onchange=()=>{releaseInputs();renderInput();if($('input-kind').value==='audio')refreshAudioDevices().catch(()=>{});};
$('midi-connect').onclick=run(async()=>{if(inputActive())return;inputConnecting=true;renderTransport();try{if(!navigator.requestMIDIAccess)throw new Error('Web MIDI is unavailable in this browser. Use the computer keyboard or a browser that supports Web MIDI.');await engine.prepareSamples();await engine.context.resume();liveNotes??=new LiveNotes(engine,message=>setStatus(message,true));midiAccess=await navigator.requestMIDIAccess({sysex:false});midiAccess.onstatechange=refreshMidi;refreshMidi();$('input-status').textContent=midiPort?'MIDI input connected. Sustain pedal (CC64) supported; recorded as held note lengths.':'MIDI permission granted. Connect a MIDI input device.';}finally{inputConnecting=false;renderTransport();}});
$('midi-device').onchange=bindMidi;
const keyboardCodes=['KeyA','KeyW','KeyS','KeyE','KeyD','KeyF','KeyT','KeyG','KeyY','KeyH','KeyU','KeyJ','KeyK'];
document.addEventListener('keydown',e=>{if(!keyboardEnabled||e.repeat||e.metaKey||e.ctrlKey||e.altKey||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||$('help-dialog').open)return;const i=keyboardCodes.indexOf(e.code);if(i>=0){e.preventDefault();const t=project.tracks.find(t=>t.id===(inputActive()?inputTarget:$('input-track').value));inputNote('on',e.code,(t?.instrument?.type==='drums'?36:60)+i);}});
document.addEventListener('keyup',e=>{if(keyboardCodes.includes(e.code))inputNote('off',e.code,0);});
window.addEventListener('blur',releaseNotes);

function renderManagement(){
  if(!project)return;const trackSelect=$('manage-track'),sceneSelect=$('manage-scene'),trackId=trackSelect.value,sceneIndex=Number(sceneSelect.value)||0;
  trackSelect.innerHTML=project.tracks.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');if(project.tracks.some(t=>t.id===trackId))trackSelect.value=trackId;
  const names=sceneNames(project);sceneSelect.innerHTML=names.map((name,i)=>`<option value="${i}">${i+1}. ${esc(name)}</option>`).join('');sceneSelect.value=Math.min(sceneIndex,project.scenes-1);
  const index=project.tracks.findIndex(t=>t.id===trackSelect.value),t=project.tracks[index];$('manage-track-name').value=t.name;$('manage-track-color').value=t.color;$('manage-scene-name').value=names[Number(sceneSelect.value)];
  renderSceneFollow(Number(sceneSelect.value));const locked=engine?.playing||inputActive()||busy;document.querySelectorAll('.set-manager input,.set-manager select,.set-manager button').forEach(el=>el.disabled=!!locked);
  $('track-left').disabled=locked||index===0;$('track-right').disabled=locked||index===project.tracks.length-1;$('track-duplicate').disabled=locked||project.tracks.length>=16;$('track-delete').disabled=locked||project.tracks.length===1;
  $('scene-up').disabled=locked||Number(sceneSelect.value)===0;$('scene-down').disabled=locked||Number(sceneSelect.value)===project.scenes-1;$('scene-duplicate').disabled=locked||project.scenes>=32;$('scene-delete').disabled=locked||project.scenes===1;
}
function applyTrack(action,value){stopToEdit();const result=editTrack(project,$('manage-track').value,action,value);installManagedProject(result.project);$('manage-track').value=result.trackId;const t=project.tracks.find(t=>t.id===result.trackId);selection={trackId:t.id,clipId:t.slots.find(Boolean)};render();changed();setStatus(action==='delete'?'Track and its Arrangement regions removed. Undo is available.':'Track updated.');}
function applyScene(action,value){stopToEdit();const result=editScene(project,Number($('manage-scene').value),action,value);installManagedProject(result.project);$('manage-scene').value=result.scene;selectedSessionScene=result.scene;render();changed();setStatus(action==='delete'?'Scene removed; existing Arrangement regions preserved. Undo is available.':'Scene updated.');}
$('manage-track').onchange=()=>{const t=project.tracks.find(t=>t.id===$('manage-track').value);selection={trackId:t.id,clipId:t.slots.find(Boolean)};selectedRegion=null;render();};$('manage-scene').onchange=()=>{selectedSessionScene=Number($('manage-scene').value);renderManagement();};
$('manage-track-name').onchange=run(()=>applyTrack('rename',$('manage-track-name').value));$('manage-track-color').onchange=run(()=>applyTrack('color',$('manage-track-color').value));$('manage-scene-name').onchange=run(()=>applyScene('rename',$('manage-scene-name').value));
$('track-left').onclick=run(()=>applyTrack('move',-1));$('track-right').onclick=run(()=>applyTrack('move',1));$('track-duplicate').onclick=run(()=>applyTrack('duplicate'));$('track-delete').onclick=run(()=>applyTrack('delete'));
