$('clip-editor').addEventListener('click',e=>{if(e.target.id==='piano-all-pitches'){noteFold=false;setPianoPitchView(0,128,3);}if(e.target.id==='piano-fit-pitches'){const notes=project.clips[selection.clipId].notes,v=fitPianoPitches(notes);if(noteFold&&notes.length)setPianoPitchView(noteBase,noteRange,Math.min(48,Math.max(3,Math.floor(288/pianoPitchRows(notes,true,noteBase,noteRange).length))));else setPianoPitchView(v.base,v.count,v.height);}});
function setPianoZoom(value,anchor,beat){if(noteGesture||velocityGesture)return;const scroll=document.querySelector('.piano-scroll'),grid=document.querySelector('.piano-grid'),clip=project.clips[selection?.clipId];if(!scroll||!grid||!clip)return;const oldWidth=grid.getBoundingClientRect().width,oldScroll=scroll.scrollLeft,viewport=scroll.clientWidth;noteZoom=pianoZoom(value);renderEditor();const next=document.querySelector('.piano-scroll'),newWidth=document.querySelector('.piano-grid').getBoundingClientRect().width;next.scrollLeft=pianoZoomScroll({oldWidth,newWidth,viewport,scroll:oldScroll,anchor,fraction:beat===undefined?undefined:beat/clip.beats});}
