function applyNote(action,options={}){stopToEdit();const c=project.clips[selection?.clipId],result=editNotes(c,action,{index:noteIndex,...options});c.notes=result.notes;noteIndex=result.selection;noteSelection=new Set([noteIndex]);const n=c.notes[noteIndex];if(n&&(n.pitch<noteBase||n.pitch>noteBase+noteRange-1))noteBase=Math.max(0,Math.min(128-noteRange,n.pitch-Math.floor((noteRange-1)/2)));engine.buffers.delete(c.id);renderEditor();changed();}
