  const id=e.target.id;if(id==='notes-stretch-percent'){noteStretchPercent=Number(e.target.value);return;}if(id==='notes-chop-parts'){noteChopParts=Number(e.target.value);return;}if(id==='note-fold'){if(noteGesture||velocityGesture)return;noteFold=e.target.checked;renderEditor();document.querySelector('.piano-scroll').scrollTop=0;revealPianoPitch();return;}if(id==='note-zoom'){setPianoZoom(Number(e.target.value));return;}if(id==='note-scope'){noteScope=e.target.value;return;}if(id==='note-strength'){noteStrength=Number(e.target.value);return;}if(id==='note-base'){setPianoPitchView(Number(e.target.value),noteRange,noteRowHeight);return;}if(id==='note-range'){setPianoPitchView(noteBase,Number(e.target.value),noteRowHeight);return;}if(id==='note-row-height'){setPianoPitchView(noteBase,noteRange,Number(e.target.value),true);return;}if(id==='note-grid'){noteGrid=Number(e.target.value);return;}if(id==='notes-paste-at'){notePasteAt=Number(e.target.value)-1;return;}if(id==='note-select'){noteIndex=Number(e.target.value);noteSelection=new Set([noteIndex]);const n=project.clips[selection.clipId].notes[noteIndex];noteBase=Math.max(0,Math.min(128-noteRange,n.pitch-Math.floor((noteRange-1)/2)));renderEditor();revealPianoPitch();return;}
