  const el=e.target.closest('[data-midi-note]');if(el){if(noteClickSuppressed)return;noteIndex=Number(el.dataset.midiNote);if(e.shiftKey){if(noteSelection.has(noteIndex))noteSelection.delete(noteIndex);else noteSelection.add(noteIndex);}else noteSelection=new Set([noteIndex]);renderEditor();focusPiano();return;}
