  if(!el)return;const index=Number(el.dataset.midiNote),indices=noteSelection.has(index)?[...noteSelection]:e.shiftKey?[...noteSelection,index]:[index];noteGesture={rows:pianoPitchRows(c.notes,noteFold,noteBase,noteRange),fold:noteFold&&c.notes.length>0,el,index,indices,note:{...c.notes[index]},clip:c,x:e.clientX,y:e.clientY,width:el.parentElement.getBoundingClientRect().width,beats:c.beats,resize:!!e.target.closest('[data-note-resize]'),pointer:e.pointerId,moved:false};el.setPointerCapture(e.pointerId);
