$('clip-editor').addEventListener('pointercancel',()=>{noteGesture=null;renderEditor();});
function focusPiano(){document.querySelector('.piano-scroll')?.focus({preventScroll:true});}
function finishGroup(result){stopToEdit();const c=project.clips[selection.clipId];c.notes=result.notes;noteSelection=new Set(result.selection);noteIndex=result.selection[0]??0;const focused=c.notes[noteIndex];if(focused&&(focused.pitch<noteBase||focused.pitch>noteBase+noteRange-1))noteBase=Math.max(0,Math.min(128-noteRange,focused.pitch-Math.floor((noteRange-1)/2)));engine.buffers.delete(c.id);renderEditor();changed();}
function applyGroup(action,options={}){stopToEdit();const c=project.clips[selection.clipId];finishGroup(editNoteGroup(c,action,{indices:[...noteSelection],...options}));}
function noteClipboardAction(action){
  const c=project.clips[selection?.clipId];if(!c||c.kind!=='midi')return;
  if(action==='all'){noteSelection=new Set(c.notes.map((n,i)=>i));renderEditor();}
  if(action==='none'){noteSelection.clear();renderEditor();}
  if(action==='copy'||action==='cut'){const copied=copyNotes(c,[...noteSelection]);if(action==='cut')applyGroup('delete');noteClipboard=copied;renderEditor();setStatus(`${copied.notes.length} notes ${action==='cut'?'cut':'copied'} to the internal clipboard.`);}
  if(action==='paste')applyGroup('paste',{clipboard:noteClipboard,at:notePasteAt});
  focusPiano();
}
$('clip-editor').addEventListener('click',run(e=>{const action={'notes-all':'all','notes-none':'none','notes-copy':'copy','notes-cut':'cut','notes-paste':'paste'}[e.target.id];if(action)noteClipboardAction(action);}));
$('clip-editor').addEventListener('keydown',run(e=>{if(!e.target.closest('.piano-scroll')||e.altKey)return;const mod=e.metaKey||e.ctrlKey;const action=mod?{KeyA:'all',KeyC:'copy',KeyX:'cut',KeyV:'paste'}[e.code]:null;if(action){e.preventDefault();e.stopPropagation();noteClipboardAction(action);}else if(!mod&&['Digit0','Numpad0'].includes(e.code)){e.preventDefault();e.stopPropagation();if(!e.repeat&&noteSelection.size){applyGroup('toggle-active');focusPiano();}}else if(!mod&&['Delete','Backspace'].includes(e.code)){e.preventDefault();e.stopPropagation();applyGroup('delete');focusPiano();}}));

$('import-midi').onclick=run(()=>{stopToEdit();$('midi-file').click();});
$('midi-file').onchange=run(async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;stopToEdit();if(file.size>2*1024*1024)throw new Error('Choose a MIDI file smaller than 2 MB.');const inspection=inspectMidi(new Uint8Array(await file.arrayBuffer()));midiPreview={inspection,name:file.name.replace(/\.midi?$/i,'')};$('midi-summary').textContent=`${file.name}: Tracks: ${inspection.groups.length} · Notes: ${inspection.groups.reduce((n,g)=>n+g.notes.length,0)}. Initial tempo ${Number(inspection.tempo.toFixed(2))} BPM. Current project ${project.bpm} BPM.`;$('midi-tracks').innerHTML=inspection.groups.map(g=>`<li>${esc(g.name)} · ${g.notes.length} notes · ${g.beats} beats</li>`).join('');$('midi-warnings').innerHTML=inspection.warnings.map(w=>`<li>${esc(w)}</li>`).join('');$('midi-mode').value='append';$('midi-tempo').checked=false;setStatus('Review MIDI notes before importing.');$('midi-dialog').showModal();});
$('midi-cancel').onclick=()=>{$('midi-dialog').close();midiPreview=null;};
$('midi-apply').onclick=run(()=>{stopToEdit();if(!midiPreview)return;const next=importMidiProject(project,midiPreview.inspection,{replace:$('midi-mode').value==='replace',useTempo:$('midi-tempo').checked,name:midiPreview.name});const first=next.tracks[next.tracks.length-midiPreview.inspection.groups.length];install(next,true);selection={trackId:first.id,clipId:first.slots[0]};render();changed();$('midi-dialog').close();midiPreview=null;setStatus('MIDI notes imported. Each track/channel has an independent Session clip.');});
$('clip-editor').addEventListener('click',run(e=>{if(e.target.id!=='midi-export')return;stopToEdit();const clip=project.clips[selection?.clipId];download(exportMidiClip(clip,project.bpm),clip.name.replace(/[^a-zA-Z0-9_-]/g,'-').slice(0,70)+'.mid','audio/midi');setStatus('MIDI clip exported at 960 ticks per beat. Notes only; silent notes omitted and lengths cut at the loop end.');}));

function automationTarget(){const track=automationChannels(project).find(t=>t.id===$('auto-track').value)||project.tracks[0],target=automationTargetFor(track,$('auto-key').value,project.returns)||automationTargets(track,project.returns)[0];return {...target,track,envelope:target.envelope||{enabled:false,points:[]}};}
function updateAutomationControls(){if(!engine)return;const locked=engine.playing||inputActive()||busy;document.querySelectorAll('.automation-editor input,.automation-editor select,.automation-editor button:not(#auto-restore):not(#auto-record)').forEach(el=>el.disabled=!!locked);const {envelope}=automationTarget();$('auto-update').disabled=locked||automationPoint<0;$('auto-delete').disabled=locked||automationPoint<0;$('auto-clear').disabled=locked||!envelope.points.length;$('auto-restore').disabled=!!engine.automationTake||!engine.automationOverrides.size;$('auto-mode').disabled=!!engine.automationTake||busy||inputActive()||engine.recording;$('auto-record').disabled=busy||inputActive()||engine.recording||(engine.playing&&engine.mode!=='arrangement');$('auto-record').textContent=engine.automationTake?'■ Finish automation':'● Record automation';$('auto-record').setAttribute('aria-pressed',!!engine.automationTake);$('auto-record').classList.toggle('recording',!!engine.automationTake);$('auto-restore').classList.toggle('overridden',engine.automationOverrides.size>0);}
function renderAutomation(){
  if(!project)return;const select=$('auto-track'),old=select.value;select.innerHTML=automationChannels(project).map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');if(automationChannels(project).some(t=>t.id===old))select.value=old;const channel=automationChannels(project).find(t=>t.id===select.value),oldKey=$('auto-key').value,targets=automationTargets(channel,project.returns);$('auto-key').innerHTML=targets.map(t=>`<option value="${esc(t.key)}">${esc(t.label)}</option>`).join('');if(targets.some(t=>t.key===oldKey))$('auto-key').value=oldKey;
  const {track,key,envelope,spec,fallback}=automationTarget(),v=currentViewport(),beats=v.span;automationPoint=Math.min(automationPoint,envelope.points.length-1);const point=envelope.points[automationPoint];
  $('auto-enabled').textContent=envelope.enabled?'Disable envelope':'Enable envelope';$('auto-enabled').setAttribute('aria-pressed',envelope.enabled);$('auto-status').textContent=`${envelope.points.length} points · ${envelope.enabled?'enabled':'disabled'}${engine?.automationOverrides.has(track.id+':'+key)?' · manually overridden':''}`;
  $('auto-point').innerHTML='<option value="-1">New point</option>'+envelope.points.map((p,i)=>`<option value="${i}">${i+1}. Beat ${p.beat+1} · ${Number(p.value.toFixed(3))}</option>`).join('');$('auto-point').value=automationPoint;
  $('auto-beat').value=point?point.beat+1:v.start+1;$('auto-value').min=spec.min;$('auto-value').max=spec.max;$('auto-value').step=spec.step||.01;$('auto-value').value=point?point.value:fallback;$('auto-curve').value=point?.curve||'linear';
  const y=v=>150-(v-spec.min)/(spec.max-spec.min)*140,x=b=>(b-v.start)/beats*1000,display={...envelope,enabled:true};let path=`M0 ${y(envelopeValue(display,v.start,fallback))}`;let previous=v.start;
  const bounds=[...envelope.points.filter(p=>p.beat>v.start&&p.beat<v.end).map(p=>p.beat),v.end];for(const b of bounds){const left=envelope.points.filter(p=>p.beat<=previous).at(-1),value=envelopeValue(display,b,fallback);path+=left?.curve==='linear'?` L${x(b)} ${y(value)}`:` H${x(b)} V${y(value)}`;previous=b;}
  $('auto-graph').innerHTML=`<path d="M0 80H1000 M0 10H1000 M0 150H1000" stroke="#353e46" fill="none"/><path d="${path}" stroke="${track.color}" stroke-width="2" fill="none" opacity="${envelope.enabled?1:.35}"/>`+envelope.points.map((p,i)=>p.beat>=v.start&&p.beat<=v.end?`<circle data-auto-point="${i}" cx="${x(p.beat)}" cy="${y(p.value)}" r="6" fill="${track.color}" stroke="${i===automationPoint?'#fff':'#171c20'}" stroke-width="2"/>`:'').join('');updateAutomationControls();
}
function changeAutomation(action,options={}){stopToEdit();const {owner,paramKey,specs}=automationTarget();owner.automation=editEnvelope(owner,paramKey,action,options,specs);if(action==='delete'||action==='clear')automationPoint=-1;else if(action==='set')automationPoint=owner.automation[paramKey].points.findIndex(p=>p.beat===options.beat);if(engine.context)engine.updateMix();renderAutomation();changed();}
for(const id of ['auto-track','auto-key'])$(id).onchange=()=>{automationPoint=-1;renderAutomation();};$('auto-point').onchange=()=>{automationPoint=Number($('auto-point').value);renderAutomation();};
$('auto-enabled').onclick=run(()=>changeAutomation('enable',{enabled:!automationTarget().envelope.enabled}));
function automationFields(){return {beat:Number($('auto-beat').value)-1,value:Number($('auto-value').value),curve:$('auto-curve').value};}
$('auto-add').onclick=run(()=>changeAutomation('set',automationFields()));$('auto-update').onclick=run(()=>changeAutomation('set',{...automationFields(),index:automationPoint}));$('auto-delete').onclick=run(()=>changeAutomation('delete',{index:automationPoint}));$('auto-clear').onclick=run(()=>changeAutomation('clear'));$('auto-record').onclick=run(async()=>{if(engine.automationTake){engine.finishAutomationRecording();setStatus(engine.automationError||'Automation take saved. Playback continues.');}else{if(!engine.playing){engine.overrides.clear();await engine.play('arrangement');}engine.startAutomationRecording($('auto-mode').value);}});$('auto-restore').onclick=()=>{engine.restoreAutomation();renderAutomation();setStatus('Arrangement automation re-enabled.');};
function automationPosition(event){const bounds=$('auto-graph').getBoundingClientRect(),{spec}=automationTarget(),v=currentViewport();return {beat:viewportBeat((event.clientX-bounds.left)/bounds.width,v),value:Number(Math.max(spec.min,Math.min(spec.max,spec.max-((event.clientY-bounds.top)/bounds.height*160-10)/140*(spec.max-spec.min))).toFixed(3))};}
$('auto-graph').onclick=run(e=>{if(automationClickSuppressed)return;stopToEdit();const circle=e.target.closest('[data-auto-point]');if(circle){automationPoint=Number(circle.dataset.autoPoint);renderAutomation();}else changeAutomation('set',{...automationPosition(e),curve:$('auto-curve').value});});
$('auto-graph').onpointerdown=e=>{const circle=e.target.closest('[data-auto-point]');if(!circle||engine.playing||inputActive()||e.button!==0)return;automationGesture={index:Number(circle.dataset.autoPoint),circle,x:e.clientX,y:e.clientY,pointer:e.pointerId,moved:false};circle.setPointerCapture(e.pointerId);};
$('auto-graph').onpointermove=e=>{const g=automationGesture;if(!g||g.pointer!==e.pointerId)return;if(Math.abs(e.clientX-g.x)>3||Math.abs(e.clientY-g.y)>3)g.moved=true;if(g.moved){g.next=automationPosition(e);const {spec}=automationTarget();g.circle.setAttribute('cx',(g.next.beat-currentViewport().start)/currentViewport().span*1000);g.circle.setAttribute('cy',150-(g.next.value-spec.min)/(spec.max-spec.min)*140);}};
$('auto-graph').onpointerup=run(e=>{const g=automationGesture;if(!g||g.pointer!==e.pointerId)return;automationGesture=null;if(!g.moved)return;automationClickSuppressed=true;setTimeout(()=>{automationClickSuppressed=false;},0);changeAutomation('set',{...g.next,index:g.index,curve:automationTarget().envelope.points[g.index].curve});});$('auto-graph').onpointercancel=()=>{automationGesture=null;renderAutomation();};

function sendControls(t){return `<label>OUTPUT<select data-output aria-label="${esc(t.name)} output"><option value="master" ${t.output!=='sendsOnly'?'selected':''}>Master</option><option value="sendsOnly" ${t.output==='sendsOnly'?'selected':''}>Sends only</option></select></label>`+(project.returns||[]).map(r=>`<div class="send-control"><label>${esc(r.name)}<input type="range" min="0" max="1" step=".01" value="${t.sends?.[r.id]?.amount||0}" data-send="${esc(r.id)}" aria-label="${esc(t.name)} send to ${esc(r.name)}"></label><label class="pre-send"><input type="checkbox" data-pre="${esc(r.id)}" ${t.sends?.[r.id]?.pre?'checked':''} aria-label="${esc(t.name)} pre-fader ${esc(r.name)}">Pre-fader</label></div>`).join('');}
function renderReturns(){if(!$('returns'))return;$('returns').innerHTML=(project.returns||[]).map(r=>`<div class="channel return-channel" style="--track:${r.color}" data-return="${esc(r.id)}"><input data-return-name data-routing-structural aria-label="${esc(r.name)} name" maxlength="40" value="${esc(r.name)}"><label>VOLUME<input data-return-volume type="range" min="0" max="1" step=".01" value="${r.volume}" aria-label="${esc(r.name)} volume"></label><label>PAN<input data-return-pan type="range" min="-1" max="1" step=".01" value="${r.pan}" aria-label="${esc(r.name)} pan"></label>${crossfadeControls(r)}<div class="toggles"><button data-return-mute aria-pressed="${r.mute}" class="${r.mute?'on':''}" aria-label="Mute ${esc(r.name)}">M</button><button data-return-effects>Effects</button><button data-return-remove data-routing-structural aria-label="Remove ${esc(r.name)}">×</button></div></div>`).join('')||'<p class="micro">Share a reverb or delay across tracks. Add a return, then turn up a send in the mixer.</p>';}
$('device-target').onchange=()=>{deviceTarget=$('device-target').value;renderDevices();};
$('add-return').onclick=run(()=>{stopToEdit();project.returns??=[];if(project.returns.length>=4)throw new Error('Up to four return tracks.');const r=newReturn('Return '+String.fromCharCode(65+project.returns.length));project.returns.push(r);deviceTarget=r.id;if(engine.context)engine.resetMixers();render();changed();setStatus('Return added with fully wet reverb. Turn up a track send to hear it.');});
$('returns').addEventListener('input',run(e=>{const el=e.target.closest('[data-return]');if(!el)return;const r=deviceTrack(el.dataset.return);if(e.target.hasAttribute('data-crossfade'))r.crossfade=e.target.value;if(e.target.hasAttribute('data-return-volume')){r.volume=Number(e.target.value);engine.overrideAutomation(r.id,'volume');}if(e.target.hasAttribute('data-return-pan')){r.pan=Number(e.target.value);engine.overrideAutomation(r.id,'pan');}engine.updateMix();}));
$('returns').addEventListener('change',run(e=>{const el=e.target.closest('[data-return]');if(!el)return;if(e.target.hasAttribute('data-return-name')){stopToEdit();deviceTrack(el.dataset.return).name=e.target.value.trim()||'Return';renderDevices();}changed();}));
$('returns').addEventListener('click',run(e=>{const el=e.target.closest('[data-return]');if(!el)return;const r=deviceTrack(el.dataset.return);if(e.target.hasAttribute('data-return-effects')){deviceTarget=r.id;renderDevices();$('device-chain').scrollIntoView({block:'nearest'});return;}if(e.target.hasAttribute('data-return-mute')){r.mute=!r.mute;engine.updateMix();renderReturns();changed();}if(e.target.hasAttribute('data-return-remove')){stopToEdit();project.returns=project.returns.filter(x=>x.id!==r.id);project.tracks.forEach(t=>{if(t.sends)delete t.sends[r.id];});if(deviceTarget===r.id)deviceTarget=null;if(engine.context)engine.resetMixers();render();changed();}}));


function instrumentSliders(params,s,prefix){const labels={keyTrack:'Filter key tracking',filterVelocity:'Filter velocity'};return Object.entries(params).map(([k,[min,max,step,,unit]])=>`<label>${labels[k]??k}<output>${s[k]}${unit}</output><input data-instrument-edit data-${prefix}-param="${k}" aria-label="${prefix==='synth'?'Synth':'Sampler'} ${labels[k]??k}" type="range" min="${min}" max="${max}" step="${step}" value="${s[k]}"></label>`).join('');}
function renderInstrument(t){renderMidiEffects(t);const rack=$('instrument');if(!project.tracks.some(x=>x.id===t.id)){rack.innerHTML='';return;}const s=t.instrument?.type==='sampler'?samplerParameters(t.instrument):t.instrument;
 rack.innerHTML=`<div class="instrument-heading"><strong>INSTRUMENT</strong><select id="instrument-type" data-instrument-edit aria-label="Instrument"><option value="legacy" ${!s?'selected':''}>Original tone</option><option value="poly" ${s?.type==='poly'?'selected':''}>Poly synth</option><option value="sampler" ${s?.type==='sampler'?'selected':''}>Sampler</option><option value="drums" ${s?.type==='drums'?'selected':''}>Drum rack</option></select>${s?.type==='poly'?`<select id="synth-preset" data-instrument-edit aria-label="Synth preset"><option value="">Choose preset…</option>${Object.keys(SYNTH_PRESETS).map(p=>`<option>${p}</option>`).join('')}</select>`:''}</div>`;
 if(s?.type==='drums')rack.innerHTML+=drumEditor(t);
 else if(s?.type==='poly')rack.innerHTML+=`<div class="synth-controls"><label>Waveform<select id="synth-wave" data-instrument-edit aria-label="Synth waveform">${['sine','triangle','sawtooth','square'].map(w=>`<option ${s.wave===w?'selected':''}>${w}</option>`).join('')}</select></label>${instrumentSliders(SYNTH_PARAMS,s,'synth')}</div><p class="micro">Polyphonic oscillator → low-pass filter → ADSR. Applies to MIDI clips and live MIDI/keyboard input. Stop playback to edit.</p>`;
 else if(s?.type==='sampler')rack.innerHTML+=`<div class="sample-source"><strong>${esc(s.name)}</strong><button id="sample-import" data-instrument-edit>${s.data?'Replace sample':'Import sample'}</button><button id="sample-audition" data-instrument-edit ${!s.data?'disabled':''}>Audition sample</button><button id="sample-audition-stop">Stop audition</button>${cropSampleButton(s)}</div>${samplerWave(t)}<div class="synth-controls"><label>Mode<select id="sample-mode" data-instrument-edit aria-label="Sampler mode"><option value="gate" ${s.mode==='gate'?'selected':''}>Gate · follow note length</option><option value="oneshot" ${s.mode==='oneshot'?'selected':''}>One shot · play to end</option></select></label><label>Start %<input id="sample-start" data-instrument-edit aria-label="Sampler start percent" type="number" min="0" max="99.9" step=".1" value="${Number((s.start*100).toFixed(3))}"></label><label>End %<input id="sample-end" data-instrument-edit aria-label="Sampler end percent" type="number" min=".1" max="100" step=".1" value="${Number((s.end*100).toFixed(3))}"></label><label>Direction<select id="sample-reverse" data-instrument-edit aria-label="Sampler direction"><option value="forward" ${!s.reverse?'selected':''}>Forward</option><option value="reverse" ${s.reverse?'selected':''}>Reverse trimmed sample</option></select></label><label>Filter<select id="sample-filter" data-instrument-edit aria-label="Sampler filter">${Object.entries(SAMPLER_FILTERS).map(([value,label])=>`<option value="${value}" ${s.filterType===value?'selected':''}>${label}</option>`).join('')}</select></label>${instrumentSliders(SAMPLER_PARAMS,s,'sample')}<label><input id="sample-loop" data-instrument-edit type="checkbox" ${s.loop?.enabled?'checked':''}>Sustain loop (Gate mode)</label><label>Loop start %<input id="sample-loop-start" data-instrument-edit aria-label="Sampler loop start percent" type="number" min="0" max="99.9" step=".1" value="${Number(((s.loop?.start??0)*100).toFixed(3))}"></label><label>Loop end %<input id="sample-loop-end" data-instrument-edit aria-label="Sampler loop end percent" type="number" min=".1" max="100" step=".1" value="${Number(((s.loop?.end??1)*100).toFixed(3))}"></label></div><p class="micro">Loop points are relative to the trimmed, reversed sample. Gate mode loops through release; One shot ignores the loop. Loop boundaries are not crossfaded.</p><p class="micro">Filter key tracking follows incoming pitch around MIDI 60. Positive filter velocity sensitivity lowers cutoff for softer notes; full velocity uses the base cutoff. Both are inactive with Filter off.</p><p class="micro">Crop sample keeps only the start/end range; Undo restores discarded audio. Sample is embedded in your project. Root is the original sample pitch (MIDI 60 = C4). Pitch changes playback speed. Import up to 30 MB / 60 seconds; stop playback to edit.</p>`;
 else rack.innerHTML+='<p class="micro">Choose a synth or sampler to shape this track’s MIDI sound. Audio clips and generated drum loops keep their own sound.</p>';
 rack.querySelectorAll('[data-instrument-edit]').forEach(el=>el.disabled=el.hasAttribute('data-crop-unavailable')||engine.playing||inputActive()||busy||(el.id==='sample-audition'&&!s?.data));
}
$('instrument').addEventListener('change',run(async e=>{stopToEdit();const t=deviceTrack($('device-chain').dataset.track);releaseNotes();let next=t.instrument?structuredClone(t.instrument):undefined;
 if(e.target.id==='instrument-type')next=e.target.value==='poly'?newSynth():e.target.value==='sampler'?newSampler():e.target.value==='drums'?newDrumRack():undefined;
 else if(e.target.dataset.drumParam)next.pads[drumPad-36][e.target.dataset.drumParam]=Number(e.target.value);
 else if(e.target.id==='drum-source'){const p=next.pads[drumPad-36];p.source=e.target.value;if(p.source==='sample')p.sample??=padSample();}
 else if(e.target.id==='drum-name')next.pads[drumPad-36].name=e.target.value.trim()||'Pad';
 else if(e.target.id==='drum-mute')next.pads[drumPad-36].mute=e.target.checked;
 else if(e.target.id==='drum-solo')next.pads[drumPad-36].solo=e.target.checked;
 else if(e.target.id==='drum-start')next.pads[drumPad-36].sample.start=Number(e.target.value)/100;
 else if(e.target.id==='drum-end')next.pads[drumPad-36].sample.end=Number(e.target.value)/100;
 else if(e.target.id==='drum-reverse')next.pads[drumPad-36].sample.reverse=e.target.checked;
 else if(e.target.id==='synth-preset'){if(!e.target.value)return;next=newSynth(e.target.value);}
 else if(e.target.id==='synth-wave')next.wave=e.target.value;
 else if(e.target.dataset.synthParam)next[e.target.dataset.synthParam]=Number(e.target.value);
 else if(e.target.dataset.sampleParam)next[e.target.dataset.sampleParam]=Number(e.target.value);
 else if(['sample-loop','sample-loop-start','sample-loop-end'].includes(e.target.id)){next.loop??={enabled:false,start:0,end:1};if(e.target.id==='sample-loop')next.loop.enabled=e.target.checked;else next.loop[e.target.id==='sample-loop-start'?'start':'end']=Number(e.target.value)/100;}
 else if(e.target.id==='sample-filter')next.filterType=e.target.value;
 else if(e.target.id==='sample-mode')next.mode=e.target.value;
 else if(e.target.id==='sample-reverse')next.reverse=e.target.value==='reverse';
 else if(e.target.id==='sample-start')next.start=Number(e.target.value)/100;
 else if(e.target.id==='sample-end')next.end=Number(e.target.value)/100;
 else return;
 try{if(next?.type==='sampler')validateSampler(next);if(next?.type==='drums')validateDrums(next);}catch(error){renderInstrument(t);throw error;}if(next)t.instrument=next;else delete t.instrument;renderInstrument(t);changed();if(engine.context){await engine.prepareSamples();if($('device-chain').dataset.track===t.id)renderInstrument(t);}
}));
$('instrument').addEventListener('input',e=>{const synth=e.target.dataset.synthParam,sample=e.target.dataset.sampleParam,k=synth||sample;if(k)e.target.previousElementSibling.textContent=e.target.value+(synth?SYNTH_PARAMS:SAMPLER_PARAMS)[k][4];});
$('instrument').addEventListener('click',run(async e=>{if(e.target.id==='sample-audition-stop'){liveNotes?.off('sample-preview');return;}if(e.target.id==='sample-audition'){stopToEdit();const t=deviceTrack($('device-chain').dataset.track);releaseNotes();await engine.prepareSamples();stopToEdit();liveNotes??=new LiveNotes(engine,message=>setStatus(message,true));liveNotes.on('sample-preview',t.instrument.root,.8,t.id);if($('device-chain').dataset.track===t.id)renderInstrument(t);return;}if(e.target.id!=='sample-import')return;stopToEdit();sampleImportTrack=$('device-chain').dataset.track;$('sample-file').value='';$('sample-file').click();}));
$('sample-file').onchange=run(async()=>{const file=$('sample-file').files[0];if(!file)return;stopToEdit();if(file.size>30*1024*1024)throw new Error('Choose a sampler file smaller than 30 MB.');const t=deviceTrack(sampleImportTrack),owner=project;if(!t||t.instrument?.type!=='sampler')throw new Error('Choose a sampler track first.');busy=true;renderInstrument(t);renderTransport();setStatus('Decoding sampler audio…');try{await engine.init();const bytes=await file.arrayBuffer(),buffer=await engine.context.decodeAudioData(bytes.slice(0));if(buffer.duration>60)throw new Error('Choose a sampler file 60 seconds or shorter.');stopToEdit();if(project!==owner||!project.tracks.includes(t)||t.instrument?.type!=='sampler')throw new Error('The sampler destination changed. Import the sample again.');releaseNotes();t.instrument={...t.instrument,name:file.name.slice(0,200),data:encode64(bytes),start:0,end:1};await engine.prepareSamples();changed();setStatus('Sample loaded. Play MIDI notes at its root pitch, or transpose from the keyboard.');}finally{busy=false;renderDevices();renderTransport();}});

function samplerWave(t){const raw=engine.sampleBuffers.get(t.id)?.raw,s=t.instrument;if(!raw)return '<p class="micro">Audition the sample to load its waveform.</p>';const data=raw.getChannelData(0),count=400,step=Math.max(1,Math.floor(data.length/count));let path='';for(let x=0;x<count;x++){let lo=0,hi=0;for(let j=x*step;j<Math.min(data.length,(x+1)*step);j++){lo=Math.min(lo,data[j]);hi=Math.max(hi,data[j]);}path+=`M${x} ${40-hi*36}V${40-lo*36}`;}const loop=s.loop,span=s.end-s.start,loopFrom=loop&&(s.reverse?s.end-span*loop.end:s.start+span*loop.start),loopTo=loop&&(s.reverse?s.end-span*loop.start:s.start+span*loop.end);return `<svg class="sample-wave" viewBox="0 0 400 80" preserveAspectRatio="none" role="img" aria-label="Sample waveform with trim and sustain loop range"><rect x="${s.start*400}" y="0" width="${(s.end-s.start)*400}" height="80" fill="#b9caa0" opacity=".12"/>${loop?.enabled?`<rect x="${loopFrom*400}" y="0" width="${(loopTo-loopFrom)*400}" height="80" fill="#8fb3d9" opacity=".2"/><path d="M${loopFrom*400} 0V80M${loopTo*400} 0V80" stroke="#8fb3d9" stroke-dasharray="3 2"/>`:""}<path d="${path}" stroke="#b9caa0" stroke-width=".7"/><path d="M${s.start*400} 0V80M${s.end*400} 0V80" stroke="#d9ef95"/></svg>`;}

function drumEditor(t){const rack=t.instrument,p=rack.pads[drumPad-36]||rack.pads[0],order=[12,13,14,15,8,9,10,11,4,5,6,7,0,1,2,3];return `<div class="drum-layout"><div class="drum-pads">${order.map(i=>{const pad=rack.pads[i];return `<button data-drum-pad="${pad.pitch}" class="drum-pad ${pad.pitch===p.pitch?'selected':''} ${pad.mute?'muted':''}" aria-label="Play ${esc(pad.name)} pad ${pad.pitch}" aria-pressed="${pad.pitch===p.pitch}"><small>${pad.pitch}</small><strong>${esc(pad.name)}</strong><span>${pad.solo?'SOLO':pad.mute?'MUTED':DRUM_SOURCES[pad.source]}</span></button>`;}).join('')}</div><div class="drum-editor"><div class="instrument-heading"><strong>PAD ${p.pitch}</strong><button id="drum-new-clip" data-instrument-edit>New drum clip</button></div><div class="synth-controls"><label>Name<input id="drum-name" data-instrument-edit aria-label="Drum pad name" maxlength="40" value="${esc(p.name)}"></label><label>Sound<select id="drum-source" data-instrument-edit aria-label="Drum sound">${Object.entries(DRUM_SOURCES).map(([k,v])=>`<option value="${k}" ${p.source===k?'selected':''}>${v}</option>`).join('')}</select></label>${Object.entries(DRUM_PARAMS).map(([k,[min,max,step,,unit]])=>`<label>${k==='decay'?'Decay (generated)':k}<output>${p[k]}${unit}</output><input data-instrument-edit data-drum-param="${k}" aria-label="Drum ${k}" type="range" min="${min}" max="${max}" step="${step}" value="${p[k]}"></label>`).join('')}</div><div class="drum-flags"><label><input id="drum-mute" data-instrument-edit type="checkbox" ${p.mute?'checked':''}>Mute pad</label><label><input id="drum-solo" data-instrument-edit type="checkbox" ${p.solo?'checked':''}>Solo pad</label></div>${p.source==='sample'?`<div class="sample-source"><strong>${esc(p.sample.name)}</strong><button id="drum-import" data-instrument-edit>Import pad sample</button>${cropSampleButton(p.sample)}</div><div class="synth-controls"><label>Start %<input id="drum-start" data-instrument-edit aria-label="Drum sample start percent" type="number" min="0" max="99.9" step=".1" value="${p.sample.start*100}"></label><label>End %<input id="drum-end" data-instrument-edit aria-label="Drum sample end percent" type="number" min=".1" max="100" step=".1" value="${p.sample.end*100}"></label><label><input id="drum-reverse" data-instrument-edit type="checkbox" ${p.sample.reverse?'checked':''}>Reverse sample</label></div>`:''}<p class="micro">Click a pad to play/select. MIDI notes 36–51 trigger pads. Matching choke groups cut each other off; 0 disables choke. Pad hits record when this track is the MIDI take destination. Generated starter loops keep their original sounds; create a MIDI drum clip to use this rack.</p></div></div>`;}
$('instrument').addEventListener('input',e=>{const k=e.target.dataset.drumParam;if(k)e.target.previousElementSibling.textContent=e.target.value+DRUM_PARAMS[k][4];});
$('instrument').addEventListener('click',run(async e=>{const pad=e.target.closest('[data-drum-pad]'),t=deviceTrack($('device-chain').dataset.track);if(t?.instrument?.type!=='drums')return;if(pad){drumPad=Number(pad.dataset.drumPad);await engine.prepareSamples();liveNotes??=new LiveNotes(engine,message=>setStatus(message,true));const key='pad:'+drumPad;if(midiTake&&inputTarget===t.id){inputNote('on',key,drumPad,.8);inputNote('off',key,0);}else{liveNotes.on(key,drumPad,.8,t.id);liveNotes.off(key);}if($('device-chain').dataset.track===t.id)renderInstrument(t);return;}if(e.target.id==='drum-new-clip'){stopToEdit();noteBase=36;commitInput({id:uid(),name:'Rack beat',kind:'midi',beats:4,sourceBpm:project.bpm,notes:drumPattern()},null,t.id);return;}if(e.target.id==='drum-import'){stopToEdit();drumImportTarget={track:t.id,pitch:drumPad};$('drum-file').value='';$('drum-file').click();}}));
$('drum-file').onchange=run(async()=>{const file=$('drum-file').files[0];if(!file)return;stopToEdit();if(file.size>30*1024*1024)throw new Error('Choose a sample smaller than 30 MB.');const t=deviceTrack(drumImportTarget?.track),pitch=drumImportTarget?.pitch,owner=project;if(t?.instrument?.type!=='drums')throw new Error('Choose a drum rack first.');busy=true;renderInstrument(t);renderTransport();try{await engine.init();const bytes=await file.arrayBuffer(),buffer=await engine.context.decodeAudioData(bytes.slice(0));if(buffer.duration>60)throw new Error('Choose a sample 60 seconds or shorter.');stopToEdit();if(owner!==project||!project.tracks.includes(t)||t.instrument?.type!=='drums')throw new Error('The drum destination changed. Import again.');releaseNotes();const next=structuredClone(t.instrument),p=next.pads[pitch-36];p.source='sample';p.sample={...padSample(),name:file.name.slice(0,200),data:encode64(bytes)};t.instrument=next;await engine.prepareSamples();changed();setStatus('Drum sample loaded. Click its pad to audition.');}finally{busy=false;renderDevices();renderTransport();}});

function animateDeviceAutomation(){if(!engine.playing)return;for(const el of $('mixer').querySelectorAll('[data-send]')){const t=project.tracks.find(t=>t.id===el.closest('[data-channel]').dataset.channel),m=t&&engine.mixer(t.id),id=el.dataset.send;if(m&&engine.automationActive(t,sendKey(id)))el.value=m.sends.get(id)[t.sends?.[id]?.pre?'pre':'post'].gain.value;}const t=deviceTrack($('device-chain').dataset.track),m=t&&engine.mixer(t.id);if(m)for(const card of $('device-chain').querySelectorAll('[data-device]')){const d=t.devices.find(d=>d.id===card.dataset.device);if(!d)continue;for(const input of card.querySelectorAll('[data-device-param]')){const key=input.dataset.deviceParam;if(!engine.automationActive(t,deviceKey(d.id,key)))continue;const value=m.chain.value(d.id,key);if(!Number.isFinite(value))continue;input.value=value;input.previousElementSibling.textContent=deviceParameterText(d.type,key,value);}}for(const el of $('returns').querySelectorAll('[data-return]')){const r=deviceTrack(el.dataset.return),m=engine.mixer(r.id);if(!m)continue;for(const key of ['volume','pan'])if(engine.automationActive(r,key))el.querySelector('[data-return-'+key+']').value=key==='volume'?m.gain.gain.value:m.pan.pan.value;}}

// Track real pointer/key gestures separately from change events: keyboard ranges
// may emit change on every keydown, while a pointer can be released off-control.
const automationPointers=new Map(),automationKeys=new Map();
const automationAdjustKeys=new Set(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End','PageUp','PageDown']);
function automationControl(el){
  if(!(el instanceof HTMLInputElement))return null;
  const channel=el.closest('[data-channel]'),ret=el.closest('[data-return]'),device=el.closest('[data-device]');
  if(channel&&el.dataset.send)return {trackId:channel.dataset.channel,key:sendKey(el.dataset.send)};
  if(channel&&(el.hasAttribute('data-volume')||el.hasAttribute('data-pan')))return {trackId:channel.dataset.channel,key:el.hasAttribute('data-volume')?'volume':'pan'};
  if(ret&&(el.hasAttribute('data-return-volume')||el.hasAttribute('data-return-pan')))return {trackId:ret.dataset.return,key:el.hasAttribute('data-return-volume')?'volume':'pan'};
  if(device&&el.dataset.deviceParam)return {trackId:$('device-chain').dataset.track,key:deviceKey(device.dataset.device,el.dataset.deviceParam)};
  return null;
}
function releaseAutomationGesture(el){const a=automationControl(el);if(a)engine.releaseAutomationControl(a.trackId,a.key);}
function automationGestureHeld(el){return [...automationPointers.values()].includes(el)||[...automationKeys.values()].includes(el);}
document.addEventListener('pointerdown',e=>{if(e.button===0&&automationControl(e.target))automationPointers.set(e.pointerId,e.target);},true);
for(const type of ['pointerup','pointercancel','lostpointercapture'])document.addEventListener(type,e=>{const el=automationPointers.get(e.pointerId);automationPointers.delete(e.pointerId);if(el&&!automationGestureHeld(el))releaseAutomationGesture(el);},true);
document.addEventListener('keydown',e=>{if(automationAdjustKeys.has(e.key)&&automationControl(e.target))automationKeys.set(e.code||e.key,e.target);},true);
document.addEventListener('keyup',e=>{const el=automationKeys.get(e.code||e.key);automationKeys.delete(e.code||e.key);if(el&&!automationGestureHeld(el))releaseAutomationGesture(el);},true);
document.addEventListener('change',e=>{if(!automationGestureHeld(e.target))releaseAutomationGesture(e.target);});
document.addEventListener('focusout',e=>{for(const [key,el]of automationKeys)if(el===e.target)automationKeys.delete(key);if(!automationGestureHeld(e.target))releaseAutomationGesture(e.target);});
window.addEventListener('blur',()=>{const controls=new Set([...automationPointers.values(),...automationKeys.values()]);automationPointers.clear();automationKeys.clear();for(const el of controls)releaseAutomationGesture(el);});

function launchOptions(value,global=false){return (global?[['global','Global'],...LAUNCH_GRIDS]:LAUNCH_GRIDS).map(([v,label])=>`<option value="${v}" ${v===value?'selected':''}>${label}</option>`).join('');}
$('launch-grid').innerHTML=launchOptions(project.transport.launchQuantization??4);$('launch-grid').onchange=()=>{project.transport.launchQuantization=Number($('launch-grid').value);changed();};

function audioEditControls(clip){const e=clip.audioEdit??defaultAudioEdit(),w=clip.warp??defaultWarp();return `<div class="audio-edit-controls full"><h3>Audio clip</h3><label>Tempo mode<select data-warp="mode" aria-label="Audio tempo mode"><option value="repitch" ${w.mode==='repitch'?'selected':''}>Repitch</option><option value="stretch" ${w.mode==='stretch'?'selected':''}>Stretch · preserve pitch</option></select></label><label>Pitch (semitones)<input data-warp="semitones" aria-label="Audio stretch pitch semitones" type="number" min="-24" max="24" step=".01" value="${w.semitones}" ${w.mode!=='stretch'?'disabled':''}></label><details id="audio-voice-character" class="full"><summary>Voice character</summary><label>Pitch character<select data-warp="formantCompensation" aria-label="Audio formant preservation" ${w.mode!=='stretch'?'disabled':''}><option value="false" ${!w.formantCompensation?'selected':''}>Follow pitch</option><option value="true" ${w.formantCompensation?'selected':''}>Preserve formants</option></select></label><label>Formant shift (semitones)<input data-warp="formantSemitones" aria-label="Audio formant shift semitones" type="number" min="-24" max="24" step=".01" value="${w.formantSemitones??0}" ${w.mode!=='stretch'?'disabled':''}></label><label>Analysis pitch (Hz · 0 = Auto)<input data-warp="formantBaseHz" aria-label="Audio formant analysis pitch Hz" type="number" min="0" max="2000" step="1" value="${w.formantBaseHz??0}" ${w.mode!=='stretch'?'disabled':''}></label><p class="micro">Preserve vocal character when shifting pitch, or shift formants for a different timbre. Auto estimates the source pitch; enter an approximate pitch if tracking is unstable.</p></details><label>Direction<select data-audio-edit="reverse" aria-label="Audio clip direction"><option value="false" ${!e.reverse?'selected':''}>Forward</option><option value="true" ${e.reverse?'selected':''}>Reverse</option></select></label><label>Clip gain (dB)<input data-audio-edit="gainDb" aria-label="Audio clip gain in dB" type="number" min="-60" max="24" step=".1" value="${e.gainDb}"></label><label>Fade in (beats)<input data-audio-edit="fadeIn" aria-label="Audio clip fade in beats" type="number" min="0" max="${clip.beats}" step=".0625" value="${e.fadeIn}"></label><label>Fade out (beats)<input data-audio-edit="fadeOut" aria-label="Audio clip fade out beats" type="number" min="0" max="${clip.beats}" step=".0625" value="${e.fadeOut}"></label><button id="reset-audio-edit" type="button">Reset audio edits</button><p class="micro">Stretch prepares audio before playback; pitch is independent of tempo in Stretch mode. Original audio stays embedded. Linear fades repeat with each clip loop; overlapping fades multiply. Edit with playback stopped.</p></div>`;}
$('clip-editor').addEventListener('change',run(async e=>{const key=e.target.dataset.audioEdit;if(!key)return;stopToEdit();const clip=project.clips[selection?.clipId];try{clip.audioEdit=editAudio(clip,{[key]:key==='reverse'?e.target.value==='true':Number(e.target.value)});}catch(error){renderEditor();throw error;}await engine.prepareAudioClip(clip);renderEditor();changed();}));
$('clip-editor').addEventListener('click',run(async e=>{if(e.target.id!=='reset-audio-edit')return;stopToEdit();const clip=project.clips[selection?.clipId];delete clip.audioEdit;await engine.prepareAudioClip(clip);renderEditor();changed();}));

$('clip-editor').addEventListener('click',run(async e=>{if(e.target.id!=='consolidate-region'||busy)return;stopToEdit();const originalProject=project,currentEngine=engine,regionId=selectedRegion,region=project.arrangement.find(r=>r.id===regionId),source=project.clips[region?.clipId];if(!source)return;const signature=JSON.stringify(region),settings=JSON.stringify([source.beats,source.sourceBpm,source.audioEdit,source.warp]),data=source.data,bpm=project.bpm;busy=true;renderTransport();setStatus('Consolidating audio region…');try{const buffer=await engine.consolidate(regionId);if(project!==originalProject||engine!==currentEngine||engine.playing||project.bpm!==bpm||JSON.stringify(project.arrangement.find(r=>r.id===regionId))!==signature||source.data!==data||JSON.stringify([source.beats,source.sourceBpm,source.audioEdit,source.warp])!==settings)throw new Error('The source changed during consolidation. Try again.');const result=installConsolidation(project,regionId,encode64(floatWav(buffer)));installManagedProject(result.project);engine.cacheAudio(project.clips[result.clipId],buffer);selection={trackId:region.trackId,clipId:result.clipId};selectedRegion=regionId;render();changed();setStatus('Audio region consolidated. Original clips retained; Undo is available.');}finally{busy=false;render();}}));

function applyMidiConsolidation(trackId,start,end){if(busy)throw new Error('Finish the current operation first.');stopToEdit();const result=consolidateMidiRange(project,trackId,start,end);installManagedProject(result.project);selection={trackId,clipId:result.clipId};selectedRegion=result.regionId;render();changed();setStatus('MIDI range consolidated. Original clips retained; Undo is available.');}
$('consolidate-midi-range').onclick=run(()=>applyMidiConsolidation($('midi-range-track').value,Number($('midi-range-start').value)-1,Number($('midi-range-end').value)-1));
$('range-from-region').onclick=run(()=>{const r=project.arrangement.find(r=>r.id===selectedRegion);if(!r)throw new Error('Select an Arrangement region first.');$('midi-range-track').value=r.trackId;$('midi-range-start').value=r.start+1;$('midi-range-end').value=r.start+r.length+1;renderTimeline();});
$('clip-editor').addEventListener('click',run(e=>{if(e.target.id!=='consolidate-midi-region')return;const r=project.arrangement.find(r=>r.id===selectedRegion);if(r)applyMidiConsolidation(r.trackId,r.start,r.start+r.length);}));

for(const id of ['midi-range-track','midi-range-start','midi-range-end'])$(id).addEventListener('change',()=>renderTimeline());

function updateLocatorControls(){const locked=busy||inputActive()||engine.recording||!!engine.automationTake,empty=!(project.locators||[]).length;for(const id of ['locator-prev','locator-next','locator-go'])$(id).disabled=locked||empty;for(const id of ['locator-name','locator-beat','locator-position','locator-add'])$(id).disabled=locked||engine.playing;for(const id of ['locator-update','locator-delete','locator-loop'])$(id).disabled=locked||engine.playing||empty;document.querySelectorAll('[data-locator]').forEach(el=>el.disabled=locked);}
function renderLocators(){const el=$('locator-select'),old=el.value;el.innerHTML=(project.locators||[]).map(l=>`<option value="${esc(l.id)}">${esc(l.name)} · beat ${l.beat+1}</option>`).join('')||'<option value="">No locators</option>';if((project.locators||[]).some(l=>l.id===old))el.value=old;selectLocator();updateLocatorControls();}
function selectLocator(){const l=project.locators?.find(l=>l.id===$('locator-select').value);if(l){$('locator-name').value=l.name;$('locator-beat').value=l.beat+1;}}
$('locator-select').onchange=selectLocator;
$('locator-position').onclick=()=>{$('locator-beat').value=Math.round(engine.beat()*4)/4+1;};
for(const action of ['add','update','delete'])$('locator-'+action).onclick=run(()=>{if(busy)throw new Error('Finish the current operation first.');stopToEdit();const result=editLocator(project.locators,action,{id:$('locator-select').value,name:$('locator-name').value,beat:Number($('locator-beat').value)-1});project.locators=result.locators;changed();$('locator-select').value=result.locators.some(l=>l.id===result.id)?result.id:(result.locators[0]?.id||'');selectLocator();setStatus('Locator '+(action==='delete'?'deleted':action==='add'?'added':'updated')+'. Undo is available.');});
async function jumpLocator(l){if(!l)return setStatus('No locator in that direction.');if(busy||inputActive()||engine.recording||engine.automationTake)throw new Error('Finish recording or the current operation before jumping.');await engine.seek(l.beat);$('locator-select').value=l.id;selectLocator();setStatus(`Locator: ${l.name} · beat ${l.beat+1}.`);}
$('locator-go').onclick=run(()=>jumpLocator(project.locators?.find(l=>l.id===$('locator-select').value)));
for(const [id,direction] of [['locator-prev',-1],['locator-next',1]])$(id).onclick=run(()=>jumpLocator(adjacentLocator(project.locators,engine.beat(),direction)));
$('timeline').addEventListener('click',run(e=>{const marker=e.target.closest('[data-locator]');if(marker)return jumpLocator(project.locators?.find(l=>l.id===marker.dataset.locator));}));

$('locator-loop').onclick=run(async()=>{if(busy)throw new Error('Finish the current operation first.');stopToEdit();const start=project.locators?.find(l=>l.id===$('locator-select').value),end=start&&adjacentLocator(project.locators,start.beat,1);if(!end)throw new Error('Select a locator with another locator after it.');await updateLoop({...project.transport,loopEnabled:true,loopStart:start.beat,loopEnd:end.beat});setStatus(`Looping ${start.name} to ${end.name}.`);});

for(const action of ['copy','cut','paste'])$('time-'+action).onclick=run(async()=>{if(busy)throw new Error('Finish the current operation first.');stopToEdit();const start=Number($('time-start').value)-1,length=Number($('time-length').value);
 const copied=action==='paste'?timeClipboard:copyArrangementTime(project,start,length);
 if(action==='copy'){timeClipboard=copied;renderTransport();setStatus(`Copied ${length} beats across all tracks, automation and locators. Set Time edit start to the paste destination.`);return;}
 const next=action==='cut'?editArrangementTime(project,'delete',start,length):pasteArrangementTime(project,copied,start),span=action==='cut'?length:copied.length,position=mapTime(engine.beat(),action==='cut'?'delete':'insert',start,span);
 if(position>16384)throw new Error('The edit would move the playhead past the timeline limit.');
 timeClipboard=copied;installManagedProject(next);await engine.seek(position);render();changed();setStatus(`${span} beats ${action==='cut'?'cut':'pasted'} across all Arrangement tracks, locators and automation. Undo is available.`);
});
for(const action of ['insert','delete','duplicate'])$('time-'+action).onclick=run(async()=>{if(busy)throw new Error('Finish the current operation first.');stopToEdit();const start=Number($('time-start').value)-1,length=Number($('time-length').value),next=action==='duplicate'?duplicateArrangementTime(project,start,length):editArrangementTime(project,action,start,length),position=mapTime(engine.beat(),action==='duplicate'?'insert':action,action==='duplicate'?start+length:start,length);if(position>16384)throw new Error('The edit would move the playhead past the timeline limit.');installManagedProject(next);await engine.seek(position);render();changed();setStatus(`${length} beats ${action==='insert'?'inserted':action==='duplicate'?'duplicated':'deleted'} across all Arrangement tracks, locators and automation. Undo is available.`);});

function setViewport(v,following=false){if(gesture||automationGesture||timeSelection?.dragging)throw new Error('Finish the current drag before changing the view.');if(!following)suspendFollow();v=timelineViewport(v.start,v.span);$('timeline-start').value=v.start+1;$('timeline-bars').value=String(v.span/4);renderTimeline();renderAutomation();}
$('timeline-start').onchange=run(()=>setViewport(currentViewport()));
let timelineWheel={time:0,kind:null,zoom:0,pan:0,view:null};
$('timeline').addEventListener('wheel',e=>{
 const zoom=e.ctrlKey||e.metaKey,delta=zoom?(e.deltaY||e.deltaX):e.shiftKey?(e.deltaX||e.deltaY):e.deltaX;if(!delta||e.altKey)return;
 e.preventDefault();if(gesture||automationGesture||timeSelection?.dragging)return;
 const lane=$('timeline').querySelector('.timeline-ruler .timeline-lane'),rect=lane?.getBoundingClientRect();if(!rect?.width)return;
 const view=currentViewport(),kind=zoom?'zoom':'pan',now=performance.now(),factor=e.deltaMode===1?16:e.deltaMode===2?rect.width:1;
 if(now-timelineWheel.time>250||timelineWheel.kind!==kind||timelineWheel.view?.start!==view.start||timelineWheel.view?.span!==view.span)timelineWheel={time:now,kind,zoom:0,pan:0,view};timelineWheel.time=now;
 let next=view;
 if(zoom){const amount=delta*factor;if(Math.sign(amount)!==Math.sign(timelineWheel.zoom))timelineWheel.zoom=0;timelineWheel.zoom=Math.max(-300,Math.min(300,timelineWheel.zoom+amount));const steps=Math.max(-3,Math.min(3,Math.trunc(timelineWheel.zoom/100)));timelineWheel.zoom-=steps*100;const anchor=Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width));for(let i=0;i<Math.abs(steps);i++)next=zoomViewport(next,Math.sign(steps),anchor);}
 else{const result=panViewport(view,delta*factor/rect.width*view.span,timelineWheel.pan);next=result.view;timelineWheel.pan=result.remainder;}
 if(next.start!==view.start||next.span!==view.span)setViewport(next);timelineWheel.view=next;
},{passive:false});

for(const [id,direction] of [['view-prev',-1],['view-next',1]])$(id).onclick=run(()=>{const v=currentViewport();setViewport(timelineViewport(v.start+direction*v.span,v.span));});
for(const [id,direction] of [['view-in',-1],['view-out',1]])$(id).onclick=run(()=>setViewport(zoomViewport(currentViewport(),direction)));
$('view-playhead').onclick=run(()=>{const v=currentViewport();setViewport(timelineViewport(Math.floor(engine.beat()/4)*4,v.span));});
$('view-fit').onclick=run(()=>{let end=4;for(const r of project.arrangement)end=Math.max(end,r.start+r.length);for(const l of project.locators||[])end=Math.max(end,l.beat+4);for(const t of automationChannels(project))for(const a of automationTargets(t,project.returns))for(const p of a.envelope?.points||[])end=Math.max(end,p.beat+1);setViewport(timelineViewport(0,fitSpan(end)));});
function zoomToSelection(){const range=loopSelectionRange();if(!range)throw new Error('Select an Arrangement time range or clip first.');const previous=currentViewport(),next=timelineViewport(range.start,fitSpan(range.length));setViewport(next);if(previous.start!==next.start||previous.span!==next.span){selectionZoomHistory.push(previous);if(selectionZoomHistory.length>16)selectionZoomHistory.shift();}updateLoopSelectionControl();}
$('view-selection').onclick=run(zoomToSelection);
$('view-back').onclick=run(()=>{const previous=selectionZoomHistory.at(-1);if(!previous)return;setViewport(previous);selectionZoomHistory.pop();updateLoopSelectionControl();});

function velocityLane(c,t){return `<div class="velocity-grid" style="--track:${t.color}"><div class="velocity-label">VEL</div><div class="velocity-lane" aria-label="MIDI velocity lane">${c.notes.map((n,i)=>`<button class="velocity-stem ${isNoteActive(n)?'':'muted-note'} ${noteSelection.has(i)?'selected':''} ${i===noteIndex?'focused':''}" data-velocity-note="${i}" role="slider" aria-label="Velocity of note ${i+1}: ${noteName(n.pitch)}${isNoteActive(n)?'':', muted'}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Number((n.velocity*100).toFixed(2))}" aria-orientation="vertical" title="Note ${i+1} · ${noteName(n.pitch)} · ${Math.round(n.velocity*100)}%" style="left:clamp(5px,${n.start/c.beats*100}%,calc(100% - 5px));height:${8+n.velocity*80}px"><i></i></button>`).join('')}</div></div>`;}
let velocityGesture=null;
function focusVelocity(index){document.querySelector(`[data-velocity-note="${index}"]`)?.focus({preventScroll:true});}
function finishVelocity(result,index){finishGroup(result);noteIndex=index;const n=project.clips[selection.clipId].notes[index];if(n&&(n.pitch<noteBase||n.pitch>noteBase+noteRange-1))noteBase=Math.max(0,Math.min(128-noteRange,n.pitch-Math.floor((noteRange-1)/2)));renderEditor();focusVelocity(index);setStatus('Note velocities updated. Undo is available.');}
$('clip-editor').addEventListener('pointerdown',e=>{const el=e.target.closest('[data-velocity-note]');if(!el||e.button!==0||engine.playing||inputActive()||busy)return;const index=Number(el.dataset.velocityNote),clip=project.clips[selection?.clipId];if(!clip||clip.kind!=='midi')return;e.preventDefault();noteIndex=index;if(e.shiftKey){if(noteSelection.has(index))noteSelection.delete(index);else noteSelection.add(index);renderEditor();focusVelocity(index);return;}if(!noteSelection.has(index))noteSelection=new Set([index]);velocityGesture={el,index,clip,indices:[...noteSelection],y:e.clientY,pointer:e.pointerId,moved:false};el.setPointerCapture(e.pointerId);});
$('clip-editor').addEventListener('pointermove',e=>{const g=velocityGesture;if(!g||g.pointer!==e.pointerId)return;const delta=(g.y-e.clientY)/80;if(Math.abs(g.y-e.clientY)>3)g.moved=true;if(!g.moved)return;g.result=editNoteGroup(g.clip,'velocity',{indices:g.indices,amount:delta});for(const i of g.indices){const stem=document.querySelector(`[data-velocity-note="${i}"]`);if(stem){stem.style.height=(8+g.result.notes[i].velocity*80)+'px';stem.setAttribute('aria-valuenow',Number((g.result.notes[i].velocity*100).toFixed(2)));stem.classList.add('selected');}}});
$('clip-editor').addEventListener('pointerup',run(e=>{const g=velocityGesture;if(!g||g.pointer!==e.pointerId)return;velocityGesture=null;try{if(busy||project.clips[selection?.clipId]!==g.clip)throw new Error('The selected clip changed during the edit.');if(g.moved&&g.result)finishVelocity(g.result,g.index);else{renderEditor();focusVelocity(g.index);}}catch(error){renderEditor();throw error;}}));
for(const type of ['pointercancel','lostpointercapture'])$('clip-editor').addEventListener(type,e=>{if(velocityGesture?.pointer!==e.pointerId)return;velocityGesture=null;renderEditor();});
$('clip-editor').addEventListener('keydown',run(e=>{const el=e.target.closest('[data-velocity-note]');if(!el||e.metaKey||e.ctrlKey||e.altKey||!['ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();if(busy)throw new Error('Finish the current operation first.');stopToEdit();const index=Number(el.dataset.velocityNote),c=project.clips[selection.clipId];if(!noteSelection.has(index))noteSelection=new Set([index]);const amount=e.key==='Home'?-c.notes[index].velocity:e.key==='End'?1-c.notes[index].velocity:(e.key==='ArrowUp'?1:-1)*(e.shiftKey?.1:.01);finishVelocity(editNoteGroup(c,'velocity',{indices:[...noteSelection],amount}),index);}));

// Hold ownership lives outside re-rendered clip buttons, so release still works
// after a grid refresh or when the pointer leaves its original element.
const gatePointers=new Map(),gateKeys=new Map();
function gateButton(target){const button=target.closest?.('[data-launch]');return button&&['gate','repeat'].includes(project.clips[button.dataset.launch]?.launch?.mode)?button:null;}
function beginGateInput(button,map,key){if(busy)throw new Error('Finish the current operation first.');if(map.has(key))return;const owner=engine,handle=owner.pressGate(button.closest('.slot').dataset.track,button.dataset.launch,Number(button.closest('.slot').dataset.scene));map.set(key,{owner,handle});run(async()=>{await handle.ready;drawWave();})();}
function endGateInput(map,key){const held=map.get(key);if(!held)return;map.delete(key);held.owner.releaseGate(held.handle);}
$('session-grid').addEventListener('pointerdown',run(e=>{const button=gateButton(e.target);if(!button||e.button!==0)return;e.preventDefault();beginGateInput(button,gatePointers,e.pointerId);}));
for(const type of ['pointerup','pointercancel'])document.addEventListener(type,e=>endGateInput(gatePointers,e.pointerId),true);
$('session-grid').addEventListener('keydown',run(e=>{const button=gateButton(e.target);if(!button||!['Space','Enter'].includes(e.code))return;e.preventDefault();e.stopPropagation();if(!e.repeat)beginGateInput(button,gateKeys,e.code);}));
document.addEventListener('keyup',e=>{if(gateKeys.has(e.code)){e.preventDefault();e.stopPropagation();endGateInput(gateKeys,e.code);}},true);
function releaseGateInputs(){for(const key of [...gatePointers.keys()])endGateInput(gatePointers,key);for(const key of [...gateKeys.keys()])endGateInput(gateKeys,key);}
window.addEventListener('blur',releaseGateInputs);
document.addEventListener('visibilitychange',()=>{if(document.hidden)releaseGateInputs();});

document.addEventListener('keydown',e=>{if(gateKeys.has(e.code)){e.preventDefault();e.stopImmediatePropagation();}},true);

function crossfadeControls(track){return `<label>CROSSFADE<select data-crossfade aria-label="${esc(track.name)} crossfade assignment">${['none','A','B'].map(value=>`<option value="${value}" ${(track.crossfade??'none')===value?'selected':''}>${value==='none'?'Unassigned':value}</option>`).join('')}</select></label>`;}
function crossfadeLabel(value){return value===0?'Center':(value<0?'A ':'B ')+Math.round(Math.abs(value)*100)+'%';}

function renderMidiEffects(t){const rack=$('midi-effects');if(!project.tracks.includes(t)){rack.innerHTML='';return;}rack.innerHTML=`<div class="instrument-heading"><strong>MIDI EFFECTS</strong><button id="add-midi-pitch" data-instrument-edit ${t.midiEffects?.length>=8?'disabled data-midi-bound':''}>+ Pitch</button><button id="add-midi-velocity" data-instrument-edit ${t.midiEffects?.length>=8?'disabled data-midi-bound':''}>+ Velocity</button><button id="add-midi-scale" data-instrument-edit ${t.midiEffects?.length>=8?'disabled data-midi-bound':''}>+ Scale</button><button id="add-midi-chord" data-instrument-edit ${t.midiEffects?.length>=8?'disabled data-midi-bound':''}>+ Chord</button><button id="add-midi-length" data-instrument-edit ${t.midiEffects?.length>=8?'disabled data-midi-bound':''}>+ Note Length</button><button id="add-midi-arp" data-instrument-edit ${t.midiEffects?.length>=8||t.midiEffects?.some(d=>d.type==='arpeggiator')?'disabled data-midi-bound':''}>+ Arpeggiator</button></div>${(t.midiEffects||[]).map((d,i)=>d.type==='arpeggiator'?arpeggiatorEffectControls(d,i,t.midiEffects.length):d.type==='length'?noteLengthEffectControls(d,i,t.midiEffects.length):d.type==='chord'?chordEffectControls(d,i,t.midiEffects.length):d.type==='scale'?scaleEffectControls(d,i,t.midiEffects.length):d.type==='velocity'?velocityEffectControls(d,i,t.midiEffects.length):`<div class="midi-effect" data-midi-effect="${esc(d.id)}"><div class="instrument-heading"><strong>${i+1}. Pitch</strong><label><input type="checkbox" data-midi-param="enabled" data-instrument-edit aria-label="Pitch ${i+1} enabled" ${d.enabled?'checked':''}> On</label><button data-midi-action="up" data-instrument-edit aria-label="Move Pitch ${i+1} up" ${i===0?'disabled data-midi-bound':''}>↑</button><button data-midi-action="down" data-instrument-edit aria-label="Move Pitch ${i+1} down" ${i===t.midiEffects.length-1?'disabled data-midi-bound':''}>↓</button><button data-midi-action="remove" data-instrument-edit aria-label="Remove Pitch ${i+1}">×</button></div><div class="synth-controls">${[['semitones','Transpose',-128,128],['lowest','Lowest MIDI note',0,127],['range','Range semitones',0,127]].map(([key,label,min,max])=>`<label>${label}<input data-midi-param="${key}" data-instrument-edit aria-label="Pitch ${i+1} ${label}" type="number" min="${min}" max="${max}" step="1" value="${d[key]}"></label>`).join('')}<label>Outside range<select data-midi-param="mode" data-instrument-edit aria-label="Pitch ${i+1} mode">${['block','fold','limit'].map(mode=>`<option value="${mode}" ${mode===d.mode?'selected':''}>${mode}</option>`).join('')}</select></label></div></div>`).join('')}<p class="micro">MIDI effects run in order before the instrument. Original clip notes and recorded input stay unchanged. Stop playback to edit.</p>`;if(engine.playing||inputActive()||busy)rack.querySelectorAll('[data-instrument-edit]').forEach(el=>el.disabled=true);}
function editMidiEffects(e){const el=e.target,action=el.dataset.midiAction,param=el.dataset.midiParam;if(!['add-midi-pitch','add-midi-velocity','add-midi-scale','add-midi-chord','add-midi-length','add-midi-arp'].includes(el.id)&&!action&&!param)return;stopToEdit();const t=deviceTrack($('device-chain').dataset.track);if(!project.tracks.includes(t))return;releaseNotes();const next=structuredClone(t.midiEffects||[]),index=next.findIndex(d=>d.id===el.closest('[data-midi-effect]')?.dataset.midiEffect);if(el.id==='add-midi-pitch')next.push(newPitch());else if(el.id==='add-midi-velocity')next.push(newVelocity());else if(el.id==='add-midi-scale')next.push(newScale());else if(el.id==='add-midi-chord')next.push(newChord());else if(el.id==='add-midi-length')next.push(newNoteLength());else if(el.id==='add-midi-arp')next.push(newArpeggiator());else if(index<0)return;else if(param?.startsWith('shifts:')||param?.startsWith('velocities:')){const [key,slot]=param.split(':');next[index][key][Number(slot)]=Number(el.value)/(key==='velocities'?100:1);}else if(param==='preset'){if(!Object.hasOwn(SCALE_PRESETS,el.value))return;next[index].map=[...SCALE_PRESETS[el.value]];}else if(param?.startsWith('map:'))next[index].map[Number(param.slice(4))]=el.value==='off'?null:Number(el.value);else if(param)next[index][param]=['enabled','fold','hold','velocityEnabled','velocityRetrigger'].includes(param)?el.checked:['mode','trigger','style','retrigger'].includes(param)?el.value:Number(el.value);else if(action==='remove')next.splice(index,1);else{const target=index+(action==='up'?-1:1);if(target<0||target>=next.length)return;[next[index],next[target]]=[next[target],next[index]];}try{validateMidiEffects(next);}catch(error){renderMidiEffects(t);throw error;}t.midiEffects=next;renderMidiEffects(t);changed();}
$('midi-effects').addEventListener('change',run(editMidiEffects));
$('midi-effects').addEventListener('click',run(e=>{if(['add-midi-pitch','add-midi-velocity','add-midi-scale','add-midi-chord','add-midi-length','add-midi-arp'].includes(e.target.id)||e.target.dataset.midiAction)editMidiEffects(e);}));

function velocityEffectControls(d,i,count){return `<div class="midi-effect" data-midi-effect="${esc(d.id)}"><div class="instrument-heading"><strong>${i+1}. Velocity</strong><label><input type="checkbox" data-midi-param="enabled" data-instrument-edit aria-label="Velocity ${i+1} enabled" ${d.enabled?'checked':''}> On</label><button data-midi-action="up" data-instrument-edit aria-label="Move Velocity ${i+1} up" ${i===0?'disabled data-midi-bound':''}>↑</button><button data-midi-action="down" data-instrument-edit aria-label="Move Velocity ${i+1} down" ${i===count-1?'disabled data-midi-bound':''}>↓</button><button data-midi-action="remove" data-instrument-edit aria-label="Remove Velocity ${i+1}">×</button></div><div class="synth-controls">${[['lowest','Input low'],['range','Input range'],['outLow','Output low'],['outHigh','Output high']].map(([key,label])=>`<label>${label}<input data-midi-param="${key}" data-instrument-edit aria-label="Velocity ${i+1} ${label}" type="number" min="0" max="127" step="1" value="${d[key]}"></label>`).join('')}<label>Mode<select data-midi-param="mode" data-instrument-edit aria-label="Velocity ${i+1} mode">${['clip','gate','fixed'].map(mode=>`<option value="${mode}" ${mode===d.mode?'selected':''}>${mode}</option>`).join('')}</select></label></div></div>`;}

function scaleEffectControls(d,i,count){const names=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'],preset=Object.keys(SCALE_PRESETS).find(k=>JSON.stringify(SCALE_PRESETS[k])===JSON.stringify(d.map))||'';return `<div class="midi-effect" data-midi-effect="${esc(d.id)}"><div class="instrument-heading"><strong>${i+1}. Scale</strong><label><input data-instrument-edit type="checkbox" data-midi-param="enabled" aria-label="Scale ${i+1} enabled" ${d.enabled?'checked':''}> On</label><button data-instrument-edit data-midi-action="up" aria-label="Move Scale ${i+1} up" ${i===0?'disabled data-midi-bound':''}>↑</button><button data-instrument-edit data-midi-action="down" aria-label="Move Scale ${i+1} down" ${i===count-1?'disabled data-midi-bound':''}>↓</button><button data-instrument-edit data-midi-action="remove" aria-label="Remove Scale ${i+1}">×</button></div><div class="synth-controls"><label>Preset<select data-instrument-edit data-midi-param="preset" aria-label="Scale ${i+1} preset"><option value="" ${!preset?'selected':''}>Custom</option>${Object.keys(SCALE_PRESETS).map(k=>`<option ${k===preset?'selected':''}>${k}</option>`).join('')}</select></label><label>Base<select data-instrument-edit data-midi-param="base" aria-label="Scale ${i+1} base">${names.map((name,j)=>`<option value="${j}" ${d.base===j?'selected':''}>${name}</option>`).join('')}</select></label>${[['transpose','Transpose',-36,36],['lowest','Lowest MIDI note',0,127],['range','Range semitones',0,127]].map(([key,label,min,max])=>`<label>${label}<input data-instrument-edit data-midi-param="${key}" aria-label="Scale ${i+1} ${label}" type="number" min="${min}" max="${max}" step="1" value="${d[key]}"></label>`).join('')}<label><input data-instrument-edit data-midi-param="fold" aria-label="Scale ${i+1} Fold" type="checkbox" ${d.fold?'checked':''}> Fold to nearest octave</label></div><div class="synth-controls">${d.map.map((value,j)=>`<label>${names[(j+d.base)%12]} →<select data-instrument-edit data-midi-param="map:${j}" aria-label="Scale ${i+1} map ${j}"><option value="off" ${value===null?'selected':''}>Off</option>${names.map((_,k)=>`<option value="${k}" ${value===k?'selected':''}>${names[(k+d.base)%12]}</option>`).join('')}</select></label>`).join('')}</div></div>`;}

$('export-depth').onchange=()=>{const floating=$('export-depth').value==='32';$('export-dither').disabled=floating;if(floating)$('export-dither').value='none';};

$('export-source').onchange=()=>{const disabled=$('export-source').value!=='range';$('export-start').disabled=disabled;$('export-length').disabled=disabled;};
$('export-use-loop').onclick=()=>{$('export-source').value='range';$('export-source').onchange();$('export-start').value=project.transport.loopStart+1;$('export-length').value=project.transport.loopEnd-project.transport.loopStart;};

$('export-midi-arrangement').onclick=run(()=>{if(engine.recording||engine.automationTake||inputActive()||busy)throw new Error('Finish recording before exporting MIDI.');const data=exportMidiArrangement(project,{applyEffects:$('export-midi-effects').checked,...($('export-source').value==='range'?{range:{start:Number($('export-start').value)-1,length:Number($('export-length').value)}}:{})});download(data,filename()+'-arrangement.mid','audio/midi');setStatus('Arrangement MIDI exported at 960 ticks per beat. Audio, instruments, mixer and audio effects are not included.');});

function renderExportChannels(){const select=$('export-channel');if(!select)return;const previous=select.value;select.innerHTML='<option value="master">Master mix</option>'+project.tracks.map(t=>`<option value="${esc('track:'+t.id)}">Track · ${esc(t.name)}</option>`).join('')+(project.returns||[]).map(t=>`<option value="${esc('return:'+t.id)}">Return · ${esc(t.name)}</option>`).join('');if([...select.options].some(o=>o.value===previous))select.value=previous;}

$('export-stems').onclick=run(async()=>{if(busy||engine.recording||engine.automationTake||inputActive())throw new Error('Finish recording before exporting stems.');const options={sampleRate:Number($('export-rate').value),bitDepth:Number($('export-depth').value),normalize:$('export-normalize').checked,dither:$('export-dither').value,includeTail:$('export-tail').checked,...($('export-source').value==='range'?{range:{start:Number($('export-start').value)-1,length:Number($('export-length').value)}}:{})},name=filename();stemAbort=new AbortController();busy=true;$('cancel-stems').disabled=false;renderTransport();try{const data=await renderStemArchive(engine,options,{signal:stemAbort.signal,onProgress:({index,total,name})=>setStatus(`Rendering stem ${index+1}/${total}: ${name}…`)});download(data,name+'-stems.zip','application/zip');setStatus('Stem ZIP exported with aligned tracks, returns and a manifest.');}catch(error){if(error.name==='AbortError')setStatus('Stem export canceled.');else throw error;}finally{stemAbort=null;busy=false;$('cancel-stems').disabled=true;renderTransport();}});
$('cancel-stems').onclick=()=>{stemAbort?.abort();setStatus('Canceling after the current channel render…');$('cancel-stems').disabled=true;};

function chordEffectControls(d,i,count){return `<div class="midi-effect" data-midi-effect="${esc(d.id)}"><div class="instrument-heading"><strong>${i+1}. Chord</strong><label><input type="checkbox" data-midi-param="enabled" data-instrument-edit aria-label="Chord ${i+1} enabled" ${d.enabled?'checked':''}> On</label><button data-midi-action="up" data-instrument-edit aria-label="Move Chord ${i+1} up" ${i===0?'disabled data-midi-bound':''}>↑</button><button data-midi-action="down" data-instrument-edit aria-label="Move Chord ${i+1} down" ${i===count-1?'disabled data-midi-bound':''}>↓</button><button data-midi-action="remove" data-instrument-edit aria-label="Remove Chord ${i+1}">×</button></div><div class="synth-controls">${d.shifts.map((shift,j)=>`<label>Voice ${j+1} shift<input data-instrument-edit data-midi-param="shifts:${j}" aria-label="Chord ${i+1} voice ${j+1} shift" type="number" min="-36" max="36" step="1" value="${shift}"></label><label>Velocity %<input data-instrument-edit data-midi-param="velocities:${j}" aria-label="Chord ${i+1} voice ${j+1} velocity" type="number" min="0" max="200" step="1" value="${Math.round(d.velocities[j]*100)}"></label>`).join('')}${[["strumMs","Strum ms",-400,400],["tension","Tension %",-100,100],["crescendo","Crescendo %",-100,100]].map(([key,label,min,max])=>`<label>${label}<input data-instrument-edit data-midi-param="${key}" aria-label="Chord ${i+1} ${label}" type="number" min="${min}" max="${max}" step="1" value="${d[key]??0}"></label>`).join('')}</div><p class="micro">Original note plus six shifted voices. A shift of 0 disables that extra voice.</p></div>`;}

function noteLengthEffectControls(d,i,count){return `<div class="midi-effect" data-midi-effect="${esc(d.id)}"><div class="instrument-heading"><strong>${i+1}. Note Length</strong><label><input type="checkbox" data-midi-param="enabled" data-instrument-edit aria-label="Note Length ${i+1} enabled" ${d.enabled?'checked':''}> On</label><button data-midi-action="up" data-instrument-edit aria-label="Move Note Length ${i+1} up" ${i===0?'disabled data-midi-bound':''}>↑</button><button data-midi-action="down" data-instrument-edit aria-label="Move Note Length ${i+1} down" ${i===count-1?'disabled data-midi-bound':''}>↓</button><button data-midi-action="remove" data-instrument-edit aria-label="Remove Note Length ${i+1}">×</button></div><div class="synth-controls"><label>Trigger<select data-midi-param="trigger" data-instrument-edit aria-label="Note Length ${i+1} trigger"><option value="on" ${(d.trigger??'on')==='on'?'selected':''}>Note On</option><option value="off" ${d.trigger==='off'?'selected':''}>Note Off</option></select></label><label>Time mode<select data-midi-param="mode" data-instrument-edit aria-label="Note Length ${i+1} mode"><option value="sync" ${d.mode==='sync'?'selected':''}>Beat sync</option><option value="time" ${d.mode==='time'?'selected':''}>Milliseconds</option></select></label>${[['milliseconds','Length ms',10,60000,1],['beats','Length beats',1/64,16,'any'],['gate','Gate %',0,200,1]].filter(([key])=>key==='gate'||key===(d.mode==='sync'?'beats':'milliseconds')).map(([key,label,min,max,step])=>`<label>${label}<input data-instrument-edit data-midi-param="${key}" aria-label="Note Length ${i+1} ${label}" type="number" min="${min}" max="${max}" step="${step}" value="${d[key]}"></label>`).join('')}${d.trigger==='off'?`<label>Release velocity (%)<input data-instrument-edit data-midi-param="releaseBlend" aria-label="Note Length ${i+1} Release velocity %" type="number" min="0" max="100" step="1" value="${d.releaseBlend??0}"></label><label>Decay ms (0 = off)<input data-instrument-edit data-midi-param="decayMs" aria-label="Note Length ${i+1} Decay ms" type="number" min="0" max="60000" step="1" value="${d.decayMs??0}"></label><label>Key Scale (%)<input data-instrument-edit data-midi-param="keyScale" aria-label="Note Length ${i+1} Key Scale %" type="number" min="-100" max="100" step="1" value="${d.keyScale??0}"></label>`:''}</div><p class="micro">Note On starts on press; Note Off starts when the incoming note ends. Gate scales the generated length. Stop cancels pending notes.</p></div>`;}

function arpeggiatorEffectControls(d,i,count){return `<div class="midi-effect" data-midi-effect="${esc(d.id)}"><div class="instrument-heading"><strong>${i+1}. Arpeggiator</strong><label><input type="checkbox" data-midi-param="enabled" data-instrument-edit aria-label="Arpeggiator ${i+1} enabled" ${d.enabled?'checked':''}> On</label><button data-midi-action="up" data-instrument-edit aria-label="Move Arpeggiator ${i+1} up" ${i===0?'disabled data-midi-bound':''}>↑</button><button data-midi-action="down" data-instrument-edit aria-label="Move Arpeggiator ${i+1} down" ${i===count-1?'disabled data-midi-bound':''}>↓</button><button data-midi-action="remove" data-instrument-edit aria-label="Remove Arpeggiator ${i+1}">×</button></div><div class="synth-controls"><label>Style<select data-midi-param="style" data-instrument-edit aria-label="Arpeggiator ${i+1} style">${Object.entries(ARP_STYLES).map(([key,label])=>`<option value="${key}" ${key===d.style?'selected':''}>${label}</option>`).join('')}</select></label><label>Rate mode<select data-midi-param="mode" data-instrument-edit aria-label="Arpeggiator ${i+1} mode"><option value="sync" ${d.mode==='sync'?'selected':''}>Beat sync</option><option value="time" ${d.mode==='time'?'selected':''}>Milliseconds</option></select></label>${[['beats','Rate beats',1/64,4,'any'],['milliseconds','Rate ms',10,2000,1],['gate','Gate %',0,200,1],['steps','Transpose steps',0,3,1],['distance','Distance semitones',-24,24,1],['offset','Pattern offset',0,127,1]].filter(([key])=>!['beats','milliseconds'].includes(key)||key===(d.mode==='sync'?'beats':'milliseconds')).map(([key,label,min,max,step])=>`<label>${label}<input data-midi-param="${key}" data-instrument-edit aria-label="Arpeggiator ${i+1} ${label}" type="number" min="${min}" max="${max}" step="${step}" value="${d[key]}"></label>`).join('')}${d.style.startsWith('random')?`<label>Random seed<input data-midi-param="seed" data-instrument-edit aria-label="Arpeggiator ${i+1} Random seed" type="number" min="1" max="4294967295" step="1" value="${d.seed??1}"></label>`:''}<label><input type="checkbox" data-midi-param="hold" data-instrument-edit aria-label="Arpeggiator ${i+1} Hold" ${d.hold?'checked':''}> Hold</label><label>Restart<select data-midi-param="retrigger" data-instrument-edit aria-label="Arpeggiator ${i+1} restart"><option value="phrase" ${d.retrigger==='phrase'?'selected':''}>After silence</option><option value="note" ${d.retrigger==='note'?'selected':''}>Every note</option><option value="beat" ${d.retrigger==='beat'?'selected':''}>Beat interval</option></select></label>${d.retrigger==='beat'?`<label>Restart beats<input type="number" data-midi-param="interval" data-instrument-edit aria-label="Arpeggiator ${i+1} Restart beats" min="0.015625" max="64" step="any" value="${d.interval??4}"></label>`:''}<label>Repeats (0 = unlimited)<input type="number" data-midi-param="repeats" data-instrument-edit aria-label="Arpeggiator ${i+1} Repeats" min="0" max="64" step="1" value="${d.repeats??0}"></label><label><input type="checkbox" data-midi-param="velocityEnabled" data-instrument-edit aria-label="Arpeggiator ${i+1} Velocity envelope" ${d.velocityEnabled?'checked':''}> Velocity envelope</label>${d.velocityEnabled?`<label>Decay ms<input type="number" data-midi-param="velocityDecayMs" data-instrument-edit aria-label="Arpeggiator ${i+1} Decay ms" min="0" max="60000" step="1" value="${d.velocityDecayMs??1000}"></label><label>Target velocity<input type="number" data-midi-param="velocityTarget" data-instrument-edit aria-label="Arpeggiator ${i+1} Target velocity" min="0" max="127" step="1" value="${d.velocityTarget??0}"></label><label><input type="checkbox" data-midi-param="velocityRetrigger" data-instrument-edit aria-label="Arpeggiator ${i+1} Restart velocity envelope" ${d.velocityRetrigger!==false?'checked':''}> Restart velocity envelope</label>`:''}</div><p class="micro">Held notes form a pattern. Transpose steps repeat it at successive distances. Hold keeps the pattern after release. Overlapping keys add or remove pitches; a fresh gesture replaces the chord. Stop cancels all notes.</p></div>`;}

let removedSoundPreset=null;
async function refreshSoundPresets(){const items=await listSoundPresets(),select=$('sound-preset-list'),selected=select.value;select.replaceChildren(...items.map(item=>{const option=document.createElement('option');option.value=item.id;option.textContent=item.name;return option;}));if(items.some(item=>item.id===selected))select.value=selected;for(const id of ['sound-preset-export','sound-preset-delete'])$(id).disabled=!items.length;document.dispatchEvent(new CustomEvent('opus-sound-presets',{detail:items}));}
function currentSound(){const track=project.tracks.find(t=>t.id===$('device-chain').dataset.track);if(!track)throw new Error('Choose a regular track to save a sound preset.');return createSoundPreset(track,$('sound-preset-name').value);}
function soundDownload(preset){download(JSON.stringify(preset,null,2),preset.name.replace(/[^a-zA-Z0-9_-]/g,'-').slice(0,60)+'.opussound','application/json');}
const presetRun=fn=>async(...args)=>{try{await fn(...args);}catch(error){$('sound-preset-status').textContent=error.message;setStatus(error.message,true);}};
$('sound-presets').onclick=presetRun(async()=>{const t=deviceTrack($('device-chain').dataset.track);$('sound-preset-name').value=t?.name||'My sound';$('sound-preset-status').textContent='';$('sound-presets-dialog').showModal();await refreshSoundPresets();});
$('close-sound-presets').onclick=()=>$('sound-presets-dialog').close();
$('sound-preset-save').onclick=presetRun(async()=>{stopToEdit();const preset=currentSound();await saveSoundPreset(preset);await refreshSoundPresets();$('sound-preset-status').textContent='Sound saved in this browser.';setStatus('Sound saved in this browser.');});
$('sound-preset-download').onclick=presetRun(()=>{stopToEdit();soundDownload(currentSound());});
$('sound-preset-export').onclick=presetRun(async()=>soundDownload(await getSoundPreset($('sound-preset-list').value)));
$('sound-preset-import').onclick=()=>{$('sound-preset-file').value='';$('sound-preset-file').click();};
$('sound-preset-file').onchange=presetRun(async()=>{const file=$('sound-preset-file').files[0];if(!file)return;if(file.size>PRESET_MAX_BYTES)throw new Error('Sound preset exceeds 90 MB.');const preset=validateSoundPreset(JSON.parse(await file.text()));await saveSoundPreset(preset);await refreshSoundPresets();$('sound-preset-status').textContent='Preset imported into this browser. Choose it in the library to load it.';setStatus('Preset imported into this browser. Choose it in the library to load it.');});
$('sound-preset-delete').onclick=presetRun(async()=>{const id=$('sound-preset-list').value,preset=await getSoundPreset(id);await removeSoundPreset(id);removedSoundPreset=preset;$('sound-preset-restore').disabled=false;await refreshSoundPresets();$('sound-preset-status').textContent='Preset removed. Undo preset removal is available until the page reloads.';setStatus('Preset removed. Undo preset removal is available until the page reloads.');});
$('sound-preset-restore').onclick=presetRun(async()=>{if(!removedSoundPreset)return;await saveSoundPreset(removedSoundPreset);removedSoundPreset=null;$('sound-preset-restore').disabled=true;await refreshSoundPresets();$('sound-preset-status').textContent='Preset restored.';setStatus('Preset restored.');});
document.addEventListener('opus-load-sound',run(async e=>{stopToEdit();if(busy)throw new Error('Finish the current operation before loading a preset.');const owner=project,target=$('device-chain').dataset.track;busy=true;renderTransport();try{const preset=await getSoundPreset(e.detail);stopToEdit();if(project!==owner)throw new Error('Project changed. Load the preset again.');const next=applySoundPreset(project,target,preset);install(next,true);deviceTarget=target;renderDevices();changed();setStatus('Loaded '+preset.name+'. Undo restores the previous sound.');}finally{busy=false;renderTransport();}}));
refreshSoundPresets().catch(()=>setStatus('Sound preset library unavailable. Project editing is still available.',true));

function renderFollow(){
 $('follow-playhead').setAttribute('aria-pressed',String(followEnabled));$('follow-resume').hidden=!followEnabled||!followSuspended;
 $('follow-state').textContent=!followEnabled?'Off':followSuspended?'Paused · manual navigation':'Following';
}
function suspendFollow(){if(followEnabled){followWasPlaying=engine.playing||!!engine.startPromise;if(!followSuspended){followSuspended=true;renderFollow();}}}
function updateFollow(beat,force=false){
 if(engine.startPromise)return;
 if(followWasPlaying!==engine.playing){followWasPlaying=engine.playing;followSuspended=false;renderFollow();}
 if(!followEnabled||followSuspended||view!=='arrangement'||(!engine.playing&&!force)||gesture||automationGesture)return;
 const next=followViewport(currentViewport(),beat);if(next)setViewport(next,true);
}
