$('follow-resume').onclick=()=>{followSuspended=false;renderFollow();updateFollow(engine.beat(),true);};
$('timeline').addEventListener('pointerdown',e=>{if(e.target.closest('[data-region],[data-seek]'))suspendFollow();},true);
