function cropSampleButton(sample){return `<button data-crop-sample data-instrument-edit ${!sample?.data||(sample.start===0&&sample.end===1)?'data-crop-unavailable disabled':''} title="Keep only the start/end range in a new embedded WAV. Undo restores the original.">Crop sample</button>`;}
$('instrument').addEventListener('click',run(async e=>{
 if(!e.target.hasAttribute('data-crop-sample')||busy)return;
 stopToEdit();const owner=project,currentEngine=engine,t=deviceTrack($('device-chain').dataset.track),instrument=t?.instrument,pitch=instrument?.type==='drums'?drumPad:undefined;
 const sample=pitch===undefined?instrument:instrument.pads[pitch-36].sample;
 if(!sample?.data)throw new Error('Load a sample before cropping.');
 const signature=JSON.stringify(instrument);busy=true;renderTransport();setStatus('Cropping sample…');
 try{
  await engine.prepareSamples();stopToEdit();
  if(owner!==project||engine!==currentEngine||!project.tracks.includes(t)||JSON.stringify(t.instrument)!==signature)throw new Error('The sample changed. Try cropping again.');
  const key=engine.sampleKey(t.id,pitch),raw=engine.sampleBuffers.get(key)?.raw;if(!raw)throw new Error('The sample could not be decoded.');
  const {buffer,wav}=cropSample(engine.context,raw,sample),cropped={...structuredClone(sample),name:sample.name.replace(/\.[^.]+$/,'').slice(0,188)+' cropped.wav',data:encode64(wav),start:0,end:1};
  const next=structuredClone(instrument);if(pitch===undefined)Object.assign(next,cropped);else next.pads[pitch-36].sample=cropped;
  if(next.type==='sampler')validateSampler(next);else validateDrums(next);
  const playable=trimSample(engine.context,buffer,cropped);
  releaseNotes();t.instrument=next;engine.sampleBuffers.set(key,{key:JSON.stringify([0,1,cropped.reverse]),data:cropped.data,raw:buffer,buffer:playable});
  changed();setStatus('Sample cropped to its start/end range. Undo restores the original.');
 }finally{busy=false;renderDevices();renderTransport();}
}));

function followControls(clip){const f=clip.follow??defaultFollow(),actions=key=>Object.entries(FOLLOW_ACTIONS).map(([value,label])=>`<option value="${value}" ${f[key]===value?'selected':''}>${label}</option>`).join('');return `<details class="full follow-settings" ${f.enabled?'open':''}><summary>Follow actions · ${f.enabled?'On':'Off'}</summary><div class="follow-fields"><label><input type="checkbox" data-follow="enabled" ${f.enabled?'checked':''}>Enable clip Follow Actions</label><label>Timing<select data-follow="linked" aria-label="Follow timing"><option value="true" ${f.linked?'selected':''}>Linked to clip loops</option><option value="false" ${!f.linked?'selected':''}>Fixed beat interval</option></select></label>${f.linked?`<label>Loop count<input data-follow="loops" aria-label="Follow loop count" type="number" min="1" max="999" step="1" value="${f.loops}"></label>`:`<label>After beats<input data-follow="beats" aria-label="Follow interval beats" type="number" min=".0625" max="16384" step=".0625" value="${f.beats}"></label>`}<label>Action A<select data-follow="a" aria-label="Follow action A">${actions('a')}</select></label><label>Action B<select data-follow="b" aria-label="Follow action B">${actions('b')}</select></label><label>Chance A %<input data-follow="chance" aria-label="Follow chance A percent" type="number" min="0" max="100" step="1" value="${f.chance}"></label><span>Chance B: ${100-f.chance}%</span>${['A','B'].filter(side=>f[side.toLowerCase()]==='jump').map(side=>`<label>Jump ${side} to scene<input data-follow="jump${side}" aria-label="Follow jump ${side} scene" type="number" min="1" max="32" step="1" value="${f['jump'+side]}"></label>`).join('')}</div><p class="micro">Empty slots divide groups. Jump uses the numbered slot on this track; an empty target does nothing. Record Session to capture the resulting sequence.</p></details>`;}
$('clip-editor').addEventListener('change',run(e=>{
 const key=e.target.dataset.follow;if(!key)return;stopToEdit();const clip=project.clips[selection?.clipId],f={...(clip.follow??defaultFollow())};f[key]=key==='enabled'?e.target.checked:key==='linked'?e.target.value==='true':['a','b'].includes(key)?e.target.value:Number(e.target.value);
 try{validateFollow(f);clip.follow=f;changed();}finally{renderEditor();const details=$('clip-editor').querySelector('.follow-settings');if(details)details.open=true;}
}));
$('follow-actions-global').onclick=()=>{if(busy||inputActive())return;engine.setFollowEnabled(project.transport.followActionsEnabled===false);};

function renderSceneFollow(index){
 const f=project.sceneFollows?.[index]??{...defaultFollow(),linked:false},options=key=>Object.entries(FOLLOW_ACTIONS).map(([v,label])=>`<option value="${v}" ${f[key]===v?'selected':''}>${label}</option>`).join('');
 $('scene-follow-editor').innerHTML=`<h3>Scene Follow Actions</h3><div class="follow-fields"><label><input type="checkbox" data-scene-follow="enabled" ${f.enabled?'checked':''}>Enable scene Follow Actions</label><label>After beats<input type="number" data-scene-follow="beats" aria-label="Scene follow interval beats" min=".0625" max="16384" step=".0625" value="${f.beats}"></label><label>Action A<select data-scene-follow="a" aria-label="Scene follow action A">${options('a')}</select></label><label>Action B<select data-scene-follow="b" aria-label="Scene follow action B">${options('b')}</select></label><label>Chance A %<input type="number" data-scene-follow="chance" aria-label="Scene follow chance A percent" min="0" max="100" value="${f.chance}"></label><span>Chance B: ${100-f.chance}%</span>${['A','B'].filter(side=>f[side.toLowerCase()]==='jump').map(side=>`<label>Jump ${side} to scene<input type="number" data-scene-follow="jump${side}" aria-label="Scene follow jump ${side}" min="1" max="32" value="${f['jump'+side]}"></label>`).join('')}</div><p class="micro">All scene rows form one group, including empty scenes. Stop stops every track. Scene transitions take precedence over clip Follow Actions; Keep playing slots retain their clips.</p>`;
}
$('scene-follow-editor').addEventListener('change',run(e=>{
 const key=e.target.dataset.sceneFollow;if(!key)return;stopToEdit();const index=Number($('manage-scene').value),f={...(project.sceneFollows?.[index]??{...defaultFollow(),linked:false})};f[key]=key==='enabled'?e.target.checked:['a','b'].includes(key)?e.target.value:Number(e.target.value);
 try{validateFollow(f);project.sceneFollows??=Array(project.scenes).fill(null);project.sceneFollows[index]=f;changed();}finally{renderManagement();}
}));
$('session-grid').addEventListener('click',run(e=>{const button=e.target.closest('[data-scene-settings]');if(!button)return;if(busy)throw new Error('Finish the current operation first.');$('manage-set').click();$('manage-scene').value=button.dataset.sceneSettings;selectedSessionScene=Number(button.dataset.sceneSettings);renderManagement();}));

async function applyWarpSettings(next,clip=project.clips[selection?.clipId],focusIndex){
 const voiceOpen=$('audio-voice-character')?.open,warpOpen=$('warp-timing')?.open;stopToEdit();if(busy)throw new Error('Finish the current operation first.');
 const owner=project,currentEngine=engine,signature=JSON.stringify(clip),bpm=project.bpm;
 try{validateWarp(next);}catch(error){renderEditor();if(warpOpen&&$('warp-timing'))$('warp-timing').open=true;throw error;}
 busy=true;renderTransport();setStatus('Preparing audio timing and pitch…');
 try{await engine.prepareAudioClip({...clip,warp:next});stopToEdit();if(project!==owner||engine!==currentEngine||project.bpm!==bpm||JSON.stringify(clip)!==signature||project.clips[clip.id]!==clip)throw new Error('The clip changed during preparation. Try again.');clip.warp=next;changed();setStatus('Audio tempo mode updated. Undo restores the previous setting.');}
 finally{busy=false;renderEditor();if(voiceOpen&&$('audio-voice-character'))$('audio-voice-character').open=true;if(warpOpen&&$('warp-timing'))$('warp-timing').open=true;renderTransport();if(focusIndex!==undefined)document.querySelector(`[data-warp-handle="${focusIndex}"]`)?.focus({preventScroll:true});}
}
$('clip-editor').addEventListener('change',run(async e=>{
 const key=e.target.dataset.warp;if(!key)return;const clip=project.clips[selection?.clipId],next={...(clip.warp??defaultWarp()),[key]:key==='mode'?e.target.value:key==='formantCompensation'?e.target.value==='true':Number(e.target.value)};await applyWarpSettings(next,clip);
}));
function warpTimingControls(c){const w=c.warp??defaultWarp(),markers=w.markers??[],disabled=w.mode!=='stretch'?'disabled':'';return `<div class="warp-marker-lane" aria-label="Warp marker handles">${markers.map((m,i)=>`<button type="button" class="warp-marker" data-warp-handle="${i}" style="left:${m.target*100}%" aria-label="Warp marker ${i+1}, target beat ${(1+m.target*c.beats).toFixed(3)}" title="Drag or use arrow keys; Delete removes" ${disabled}>${i+1}</button>`).join('')}</div><details id="warp-timing"><summary>Warp timing · ${markers.length} markers</summary><p class="micro">Clip-relative beats, starting at 1. Start and end stay fixed. Source points stay in order; moving Target changes when they play.</p><div class="warp-marker-actions"><button type="button" id="warp-add" ${disabled}>Add marker</button><button type="button" id="warp-clear" ${disabled||(!markers.length?'disabled':'')}>Reset timing</button></div><div class="warp-marker-rows">${markers.map((m,i)=>`<div class="warp-marker-row"><span>${i+1}</span><label>Source beat<input data-warp-marker-field="source" data-marker-index="${i}" aria-label="Warp marker ${i+1} source beat" type="number" step=".0625" value="${Number((1+m.source*c.beats).toFixed(6))}" ${disabled}></label><label>Target beat<input data-warp-marker-field="target" data-marker-index="${i}" aria-label="Warp marker ${i+1} target beat" type="number" step=".0625" value="${Number((1+m.target*c.beats).toFixed(6))}" ${disabled}></label><button type="button" data-warp-remove="${i}" aria-label="Remove Warp marker ${i+1}" ${disabled}>×</button></div>`).join('')}</div></details>`;}
function markerClip(){const clip=project.clips[selection?.clipId];if(clip?.kind!=='audio'||clip.warp?.mode!=='stretch')throw new Error('Choose Stretch mode to edit Warp markers.');return clip;}
async function applyMarkers(clip,markers,focusIndex){await applyWarpSettings({...clip.warp,markers},clip,focusIndex);}
$('clip-editor').addEventListener('change',run(async e=>{const key=e.target.dataset.warpMarkerField;if(!key)return;const clip=markerClip(),markers=structuredClone(clip.warp.markers??[]),i=Number(e.target.dataset.markerIndex);markers[i][key]=(Number(e.target.value)-1)/clip.beats;await applyMarkers(clip,markers);}));
$('clip-editor').addEventListener('click',run(async e=>{const remove=e.target.dataset.warpRemove,id=e.target.id;if(remove===undefined&&!['warp-add','warp-clear'].includes(id))return;const clip=markerClip(),markers=structuredClone(clip.warp.markers??[]);if(remove!==undefined){markers.splice(Number(remove),1);await applyMarkers(clip,markers);}else if(id==='warp-clear')await applyMarkers(clip,[]);else{const points=[0,...markers.map(m=>m.target),1];let start=0,length=0;for(let i=0;i<points.length-1;i++)if(points[i+1]-points[i]>length){start=points[i];length=points[i+1]-points[i];}await applyMarkers(clip,insertWarpMarker(markers,start+length/2));}}));
$('clip-editor').addEventListener('dblclick',run(async e=>{if(e.target.id!=='waveform')return;const clip=project.clips[selection?.clipId];if(clip?.kind!=='audio'||clip.warp?.mode!=='stretch')return;const rect=e.target.getBoundingClientRect(),target=(e.clientX-rect.left)/rect.width;await applyMarkers(clip,insertWarpMarker(clip.warp.markers,target));}));
let warpDrag;
$('clip-editor').addEventListener('pointerdown',run(e=>{const handle=e.target.closest('[data-warp-handle]');if(!handle||handle.disabled||e.button!==0)return;stopToEdit();if(busy)throw new Error('Finish the current operation first.');const clip=markerClip(),index=Number(handle.dataset.warpHandle);warpDrag={clip,index,signature:JSON.stringify(clip),handle,pointer:e.pointerId,rect:handle.parentElement.getBoundingClientRect(),target:clip.warp.markers[index].target};handle.setPointerCapture(e.pointerId);e.preventDefault();handle.focus();}));
window.addEventListener('pointermove',e=>{const d=warpDrag;if(!d||e.pointerId!==d.pointer)return;const m=d.clip.warp.markers,min=(m[d.index-1]?.target??0)+.0001,max=(m[d.index+1]?.target??1)-.0001;d.target=Math.max(min,Math.min(max,(e.clientX-d.rect.left)/d.rect.width));d.handle.style.left=d.target*100+'%';});
window.addEventListener('pointerup',run(async e=>{const d=warpDrag;if(!d||e.pointerId!==d.pointer)return;warpDrag=null;if(project.clips[d.clip.id]!==d.clip||selection?.clipId!==d.clip.id||JSON.stringify(d.clip)!==d.signature){renderEditor();return;}const markers=structuredClone(d.clip.warp.markers);if(Math.abs(markers[d.index].target-d.target)<1e-9)return;markers[d.index].target=d.target;await applyMarkers(d.clip,markers,d.index);}));
window.addEventListener('pointercancel',e=>{if(warpDrag?.pointer===e.pointerId){warpDrag=null;renderEditor();}});
$('clip-editor').addEventListener('keydown',run(async e=>{const handle=e.target.closest('[data-warp-handle]');if(!handle||!['ArrowLeft','ArrowRight','Delete','Backspace','Escape'].includes(e.key))return;e.preventDefault();if(e.key==='Escape'){warpDrag=null;renderEditor();return;}const clip=markerClip(),index=Number(handle.dataset.warpHandle),markers=structuredClone(clip.warp.markers);if(e.key==='Delete'||e.key==='Backspace')markers.splice(index,1);else markers[index].target+=(e.key==='ArrowRight'?1:-1)*(e.shiftKey?1:1/16)/clip.beats;await applyMarkers(clip,markers,index);}));
